import React, { useCallback, useEffect, useRef, useState } from 'react';
import RFB from '@novnc/novnc';
import apiService from '../services/apiService';
import API_CONFIG from '../config/api';
import LoadingSpinner from '../components/LoadingSpinner';
import Notification from '../components/Notification';

function buildVncWebSocketUrl(serverId) {
  const token = localStorage.getItem('auth_token');
  if (!token) {
    throw new Error('You must be signed in to open a VNC session.');
  }
  const base = new URL(API_CONFIG.BASE_URL);
  const wsProto = base.protocol === 'https:' ? 'wss:' : 'ws:';
  const path = `/api/v1/vnc/ws/${encodeURIComponent(serverId)}?token=${encodeURIComponent(token)}`;
  return `${wsProto}//${base.host}${path}`;
}

/** noVNC RFB options — see @novnc/novnc docs (compressionLevel 0–9, qualityLevel 0–9). */
const VNC_PRESET_OPTIONS = {
  balanced: {
    shared: true,
    scaleViewport: true,
    clipViewport: false,
    compressionLevel: 2,
    qualityLevel: 6,
    resizeSession: false,
  },
  low_bandwidth: {
    shared: true,
    scaleViewport: true,
    clipViewport: false,
    compressionLevel: 9,
    qualityLevel: 2,
    resizeSession: false,
  },
  high_quality: {
    shared: true,
    scaleViewport: true,
    clipViewport: false,
    compressionLevel: 0,
    qualityLevel: 9,
    resizeSession: false,
  },
};

const LS_VNC_PRESET = 'vnc_connection_preset';
const LS_VNC_VIEW_ONLY = 'vnc_view_only';

function buildRfbOptions(presetId, viewOnly, credentials) {
  const base = VNC_PRESET_OPTIONS[presetId] || VNC_PRESET_OPTIONS.balanced;
  const options = { ...base, viewOnly };
  if (credentials) {
    options.credentials = credentials;
  }
  return options;
}

const VncManager = () => {
  const [servers, setServers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [notification, setNotification] = useState(null);
  const [name, setName] = useState('');
  const [host, setHost] = useState('');
  const [port, setPort] = useState('5900');
  const [password, setPassword] = useState('');
  const [clearPassword, setClearPassword] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [saving, setSaving] = useState(false);

  const [activeServer, setActiveServer] = useState(null);
  const [sessionStatus, setSessionStatus] = useState('idle');
  const [sessionIsFullscreen, setSessionIsFullscreen] = useState(false);
  const [connectionPreset, setConnectionPreset] = useState(() => {
    try {
      const s = localStorage.getItem(LS_VNC_PRESET);
      if (s && Object.prototype.hasOwnProperty.call(VNC_PRESET_OPTIONS, s)) return s;
    } catch {
      /* ignore */
    }
    return 'balanced';
  });
  const [viewOnly, setViewOnly] = useState(() => {
    try {
      return localStorage.getItem(LS_VNC_VIEW_ONLY) === '1';
    } catch {
      return false;
    }
  });
  const screenRef = useRef(null);
  const rfbRef = useRef(null);
  /** Fullscreen only the VNC viewport (not the Session header / connection profile). */
  const vncViewportFullscreenRef = useRef(null);
  /** True if connect used a password from server config (for modal messaging). */
  const connectHadStoredVncPasswordRef = useRef(false);
  /** Increments each `credentialsrequired` for this connection (retry messaging). */
  const vncAuthPromptCountRef = useRef(0);
  const vncAuthPasswordInputRef = useRef(null);

  const [vncAuthModalOpen, setVncAuthModalOpen] = useState(false);
  const [vncAuthPasswordInput, setVncAuthPasswordInput] = useState('');
  const [vncAuthFieldError, setVncAuthFieldError] = useState('');
  const [vncAuthMessage, setVncAuthMessage] = useState('');

  useEffect(() => {
    try {
      localStorage.setItem(LS_VNC_PRESET, connectionPreset);
    } catch {
      /* ignore */
    }
  }, [connectionPreset]);

  useEffect(() => {
    try {
      localStorage.setItem(LS_VNC_VIEW_ONLY, viewOnly ? '1' : '0');
    } catch {
      /* ignore */
    }
  }, [viewOnly]);

  const loadServers = useCallback(async () => {
    setLoading(true);
    try {
      const list = await apiService.getVncServers();
      setServers(Array.isArray(list) ? list : []);
    } catch (e) {
      setNotification({ type: 'error', message: e.message || 'Failed to load VNC servers' });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadServers();
  }, [loadServers]);

  const syncSessionFullscreenFlag = useCallback(() => {
    const el =
      typeof document !== 'undefined'
        ? document.fullscreenElement ||
          document.webkitFullscreenElement ||
          document.mozFullScreenElement ||
          document.msFullscreenElement
        : null;
    const viewport = vncViewportFullscreenRef.current;
    setSessionIsFullscreen(!!viewport && el === viewport);
    requestAnimationFrame(() => {
      window.dispatchEvent(new Event('resize'));
    });
  }, []);

  useEffect(() => {
    syncSessionFullscreenFlag();
    document.addEventListener('fullscreenchange', syncSessionFullscreenFlag);
    document.addEventListener('webkitfullscreenchange', syncSessionFullscreenFlag);
    document.addEventListener('mozfullscreenchange', syncSessionFullscreenFlag);
    document.addEventListener('MSFullscreenChange', syncSessionFullscreenFlag);
    return () => {
      document.removeEventListener('fullscreenchange', syncSessionFullscreenFlag);
      document.removeEventListener('webkitfullscreenchange', syncSessionFullscreenFlag);
      document.removeEventListener('mozfullscreenchange', syncSessionFullscreenFlag);
      document.removeEventListener('MSFullscreenChange', syncSessionFullscreenFlag);
    };
  }, [syncSessionFullscreenFlag]);

  const exitSessionFullscreen = useCallback(async () => {
    try {
      if (document.exitFullscreen) await document.exitFullscreen();
      else if (document.webkitExitFullscreen) await document.webkitExitFullscreen();
      else if (document.mozCancelFullScreen) await document.mozCancelFullScreen();
      else if (document.msExitFullscreen) await document.msExitFullscreen();
    } catch {
      /* ignore */
    }
  }, []);

  const toggleSessionFullscreen = useCallback(async () => {
    const viewport = vncViewportFullscreenRef.current;
    if (!viewport) return;
    try {
      if (sessionIsFullscreen) {
        await exitSessionFullscreen();
      } else {
        if (viewport.requestFullscreen) await viewport.requestFullscreen();
        else if (viewport.webkitRequestFullscreen)
          await viewport.webkitRequestFullscreen({ navigationUI: 'hide' });
        else if (viewport.mozRequestFullScreen) await viewport.mozRequestFullScreen();
        else if (viewport.msRequestFullscreen) await viewport.msRequestFullscreen();
      }
      requestAnimationFrame(() => {
        window.dispatchEvent(new Event('resize'));
      });
    } catch (err) {
      setNotification({
        type: 'error',
        message: err?.message || 'Could not enter fullscreen. Your browser may block the request.',
      });
    }
  }, [sessionIsFullscreen, exitSessionFullscreen]);

  const disconnectVnc = useCallback(() => {
    void exitSessionFullscreen();
    setVncAuthModalOpen(false);
    setVncAuthPasswordInput('');
    setVncAuthFieldError('');
    setVncAuthMessage('');
    vncAuthPromptCountRef.current = 0;
    if (rfbRef.current) {
      try {
        rfbRef.current.disconnect();
      } catch {
        /* ignore */
      }
      rfbRef.current = null;
    }
    setActiveServer(null);
    setSessionStatus('idle');
  }, [exitSessionFullscreen]);

  useEffect(() => () => disconnectVnc(), [disconnectVnc]);

  const submitVncAuthModal = useCallback(
    (e) => {
      e?.preventDefault();
      const pwd = vncAuthPasswordInput.trim();
      if (!pwd) {
        setVncAuthFieldError('Enter the VNC password.');
        return;
      }
      const rfb = rfbRef.current;
      if (!rfb || typeof rfb.sendCredentials !== 'function') {
        setVncAuthModalOpen(false);
        disconnectVnc();
        return;
      }
      setVncAuthFieldError('');
      rfb.sendCredentials({ username: '', password: pwd });
      setVncAuthModalOpen(false);
      setVncAuthPasswordInput('');
    },
    [vncAuthPasswordInput, disconnectVnc]
  );

  useEffect(() => {
    if (!vncAuthModalOpen) return undefined;
    const onKey = (ev) => {
      if (ev.key === 'Escape') {
        ev.preventDefault();
        disconnectVnc();
      }
    };
    window.addEventListener('keydown', onKey);
    const t = window.setTimeout(() => {
      vncAuthPasswordInputRef.current?.focus?.();
    }, 50);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.clearTimeout(t);
    };
  }, [vncAuthModalOpen, disconnectVnc]);

  const connectTo = async (server) => {
    disconnectVnc();
    vncAuthPromptCountRef.current = 0;
    setSessionStatus('connecting');
    setActiveServer({ id: server.id, name: server.name });

    let vncPassword = null;
    try {
      const detail = await apiService.getVncServer(server.id);
      vncPassword = detail.password || null;
    } catch (err) {
      setSessionStatus('idle');
      setActiveServer(null);
      setNotification({
        type: 'error',
        message: err.message || 'Could not load server details for VNC authentication.',
      });
      return;
    }

    connectHadStoredVncPasswordRef.current = !!vncPassword;

    const url = buildVncWebSocketUrl(server.id);
    const credentials = vncPassword ? { password: vncPassword, username: '' } : undefined;
    const options = buildRfbOptions(connectionPreset, viewOnly, credentials);

    const rfb = new RFB(screenRef.current, url, options);
    // Many servers omit cursor updates or draw the cursor in the framebuffer only.
    // Local dot cursor keeps pointer position visible (noVNC property).
    rfb.showDotCursor = true;

    rfb.addEventListener('connect', () => {
      setSessionStatus('connected');
      setNotification(null);
      setVncAuthModalOpen(false);
    });
    rfb.addEventListener('disconnect', (ev) => {
      const clean = ev.detail && ev.detail.clean;
      setSessionStatus(clean ? 'disconnected' : 'error');
      setVncAuthModalOpen(false);
      if (!clean) {
        setNotification({
          type: 'error',
          message:
            'VNC session ended unexpectedly. Check that the server is reachable from the backend, credentials, and that noVNC supports this server’s security types.',
        });
      }
      rfbRef.current = null;
      setActiveServer(null);
    });
    rfb.addEventListener('credentialsrequired', () => {
      vncAuthPromptCountRef.current += 1;
      const n = vncAuthPromptCountRef.current;
      const hadStored = connectHadStoredVncPasswordRef.current;
      let msg;
      if (n === 1 && !hadStored) {
        msg =
          'No password is saved for this server. Enter the VNC password to continue. You can save it later under Edit.';
      } else if (n === 1 && hadStored) {
        msg =
          'The saved password was not accepted. Enter the correct VNC password (or update it under Edit).';
      } else {
        msg = 'Authentication failed. Enter the password again.';
      }
      setVncAuthMessage(msg);
      setVncAuthPasswordInput('');
      setVncAuthFieldError('');
      setVncAuthModalOpen(true);
    });

    rfbRef.current = rfb;
  };

  const resetForm = () => {
    setName('');
    setHost('');
    setPort('5900');
    setPassword('');
    setClearPassword(false);
    setEditingId(null);
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    const p = parseInt(port, 10);
    if (!name.trim() || !host.trim() || Number.isNaN(p) || p < 1 || p > 65535) {
      setNotification({ type: 'error', message: 'Enter a name, host, and valid port (1–65535).' });
      return;
    }
    setSaving(true);
    try {
      if (editingId) {
        const payload = {
          name: name.trim(),
          host: host.trim(),
          port: p,
          clear_password: clearPassword,
        };
        if (password.trim()) {
          payload.password = password.trim();
        }
        await apiService.updateVncServer(editingId, payload);
        setNotification({ type: 'success', message: 'Server updated.' });
      } else {
        const payload = {
          name: name.trim(),
          host: host.trim(),
          port: p,
        };
        if (password.trim()) {
          payload.password = password.trim();
        }
        await apiService.createVncServer(payload);
        setNotification({ type: 'success', message: 'Server added.' });
      }
      resetForm();
      await loadServers();
    } catch (err) {
      setNotification({ type: 'error', message: err.message || 'Save failed' });
    } finally {
      setSaving(false);
    }
  };

  const onEdit = async (s) => {
    setEditingId(s.id);
    setName(s.name);
    setHost(s.host);
    setPort(String(s.port));
    setPassword('');
    setClearPassword(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    try {
      const detail = await apiService.getVncServer(s.id);
      if (detail.password) {
        setPassword(detail.password);
      }
    } catch (err) {
      setNotification({
        type: 'error',
        message: err.message || 'Could not load password for editing (other fields are loaded from the list).',
      });
    }
  };

  const onDelete = async (s) => {
    if (!window.confirm(`Remove “${s.name}” from the list?`)) return;
    try {
      await apiService.deleteVncServer(s.id);
      if (activeServer && activeServer.id === s.id) {
        disconnectVnc();
      }
      setNotification({ type: 'success', message: 'Removed.' });
      await loadServers();
    } catch (err) {
      setNotification({ type: 'error', message: err.message || 'Delete failed' });
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <LoadingSpinner />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">VNC</h1>
          <p className="mt-2 text-gray-600">
            Manage VNC targets and open sessions through the backend (admin only). The browser connects via{' '}
            <code className="text-sm bg-gray-200 px-1 rounded">WebSocket → backend → TCP</code>. Optional VNC passwords
            are stored in the app database as plaintext (protect the host and use HTTPS in production).
          </p>
        </div>

        {notification && (
          <div className="mb-4">
            <Notification
              message={notification.message}
              type={notification.type}
              onClose={() => setNotification(null)}
            />
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="space-y-6">
            <div className="bg-white shadow rounded-lg p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">
                {editingId ? 'Edit server' : 'Add server'}
              </h2>
              <form onSubmit={onSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700">Display name</label>
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:ring-blue-500"
                    placeholder="e.g. Build VM"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Host</label>
                  <input
                    type="text"
                    value={host}
                    onChange={(e) => setHost(e.target.value)}
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:ring-blue-500"
                    placeholder="192.168.1.10 or hostname"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Port</label>
                  <input
                    type="number"
                    min={1}
                    max={65535}
                    value={port}
                    onChange={(e) => setPort(e.target.value)}
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:ring-blue-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">VNC password (optional)</label>
                  <input
                    type="password"
                    value={password}
                    autoComplete="new-password"
                    onChange={(e) => {
                      setPassword(e.target.value);
                      if (e.target.value) setClearPassword(false);
                    }}
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:ring-blue-500"
                    placeholder={editingId ? 'Leave blank to keep current' : 'Leave blank if the server has no password'}
                  />
                  {editingId && (
                    <label className="mt-2 flex items-center gap-2 text-sm text-gray-700">
                      <input
                        type="checkbox"
                        checked={clearPassword}
                        onChange={(e) => {
                          setClearPassword(e.target.checked);
                          if (e.target.checked) setPassword('');
                        }}
                      />
                      Remove stored password
                    </label>
                  )}
                </div>
                <div className="flex gap-2">
                  <button
                    type="submit"
                    disabled={saving}
                    className="inline-flex justify-center rounded-md border border-transparent bg-blue-600 py-2 px-4 text-sm font-medium text-white shadow-sm hover:bg-blue-700 disabled:opacity-50"
                  >
                    {saving ? 'Saving…' : editingId ? 'Update' : 'Add'}
                  </button>
                  {editingId && (
                    <button
                      type="button"
                      onClick={resetForm}
                      className="inline-flex justify-center rounded-md border border-gray-300 bg-white py-2 px-4 text-sm font-medium text-gray-700 shadow-sm hover:bg-gray-50"
                    >
                      Cancel edit
                    </button>
                  )}
                </div>
              </form>
            </div>

            <div className="bg-white shadow rounded-lg overflow-hidden">
              <div className="px-6 py-4 border-b border-gray-200">
                <h2 className="text-lg font-semibold text-gray-900">Saved servers</h2>
              </div>
              {servers.length === 0 ? (
                <p className="px-6 py-8 text-gray-500 text-sm">No servers yet. Add one above.</p>
              ) : (
                <ul className="divide-y divide-gray-200">
                  {servers.map((s) => (
                    <li key={s.id} className="px-6 py-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                      <div>
                        <div className="font-medium text-gray-900">{s.name}</div>
                        <div className="text-sm text-gray-500">
                          {s.host}:{s.port}
                        </div>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        <button
                          type="button"
                          onClick={() => connectTo(s)}
                          className="rounded-md bg-green-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-green-700"
                        >
                          Connect
                        </button>
                        <button
                          type="button"
                          onClick={() => onEdit(s)}
                          className="rounded-md border border-gray-300 bg-white px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50"
                        >
                          Edit
                        </button>
                        <button
                          type="button"
                          onClick={() => onDelete(s)}
                          className="rounded-md border border-red-200 text-red-700 bg-white px-3 py-1.5 text-sm font-medium hover:bg-red-50"
                        >
                          Delete
                        </button>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>

          <div className="bg-white shadow rounded-lg p-4 flex flex-col min-h-[520px]">
            <div className="flex flex-wrap items-center justify-between gap-2 mb-3 shrink-0">
              <h2 className="text-lg font-semibold text-gray-900">Session</h2>
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-sm text-gray-500">
                  {activeServer ? `${activeServer.name} · ${sessionStatus}` : sessionStatus}
                </span>
                <button
                  type="button"
                  onClick={() => toggleSessionFullscreen()}
                  className="rounded-md border border-gray-300 bg-white px-3 py-1 text-sm font-medium text-gray-800 hover:bg-gray-50"
                >
                  {sessionIsFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
                </button>
                {(sessionStatus === 'connecting' || sessionStatus === 'connected') && (
                  <button
                    type="button"
                    onClick={disconnectVnc}
                    className="rounded-md bg-gray-200 px-3 py-1 text-sm font-medium text-gray-800 hover:bg-gray-300"
                  >
                    Disconnect
                  </button>
                )}
              </div>
            </div>

            <div className="mb-4 rounded-md border border-gray-200 bg-gray-50 px-3 py-3 text-sm shrink-0">
              <div className="font-medium text-gray-800 mb-2">Connection profile</div>
              <div className="flex flex-col sm:flex-row sm:flex-wrap sm:items-center gap-3">
                <label className="flex flex-col gap-1 min-w-[200px] flex-1">
                  <span className="text-xs text-gray-600">Preset (noVNC quality / compression)</span>
                  <select
                    value={connectionPreset}
                    onChange={(e) => setConnectionPreset(e.target.value)}
                    disabled={sessionStatus === 'connecting' || sessionStatus === 'connected'}
                    className="rounded-md border border-gray-300 bg-white px-2 py-1.5 text-sm text-gray-900 disabled:opacity-60"
                  >
                    <option value="balanced">Balanced — default speed and detail</option>
                    <option value="low_bandwidth">Slow / metered — stronger compression, lower JPEG quality</option>
                    <option value="high_quality">LAN / fast link — minimal compression, best JPEG quality</option>
                  </select>
                </label>
                <label className="flex items-center gap-2 text-gray-700 cursor-pointer shrink-0">
                  <input
                    type="checkbox"
                    checked={viewOnly}
                    onChange={(e) => setViewOnly(e.target.checked)}
                    disabled={sessionStatus === 'connecting' || sessionStatus === 'connected'}
                  />
                  View only (no keyboard or mouse to host)
                </label>
              </div>
              <p className="mt-2 text-xs text-gray-500 leading-snug">
                Presets map to noVNC&apos;s <code className="bg-gray-200 px-0.5 rounded">compressionLevel</code> and{' '}
                <code className="bg-gray-200 px-0.5 rounded">qualityLevel</code>. Changes apply on the{' '}
                <strong>next</strong> connection (disconnect first or switch preset before Connect).
              </p>
            </div>

            <div
              ref={vncViewportFullscreenRef}
              className="relative flex flex-col flex-1 min-h-[480px] min-h-0 w-full rounded-md bg-black overflow-hidden border border-gray-800 [&:fullscreen]:min-h-screen [&:fullscreen]:rounded-none [&:fullscreen]:border-0 [&:-webkit-full-screen]:min-h-screen [&:-webkit-full-screen]:rounded-none"
            >
              {sessionIsFullscreen && (
                <button
                  type="button"
                  onClick={() => exitSessionFullscreen()}
                  className="absolute top-3 right-3 z-[100] rounded-md bg-black/75 px-3 py-2 text-sm font-medium text-white shadow-lg backdrop-blur-sm hover:bg-black/90"
                >
                  Exit fullscreen
                </button>
              )}
              <div
                ref={screenRef}
                className="flex-1 min-h-0 w-full [&_canvas]:cursor-crosshair"
                style={{ cursor: 'crosshair' }}
                tabIndex={0}
              />
            </div>
            {!activeServer && sessionStatus === 'idle' && (
              <p className="text-sm text-gray-500 mt-3">
                Click <strong>Connect</strong> on a server to show the remote screen here.
              </p>
            )}
          </div>
        </div>
      </div>

      {vncAuthModalOpen && (
        <div
          className="fixed inset-0 z-[300] flex items-center justify-center bg-black/50 p-4"
          role="dialog"
          aria-modal="true"
          aria-labelledby="vnc-auth-modal-title"
        >
          <div className="w-full max-w-md rounded-lg bg-white p-6 shadow-xl">
            <h3 id="vnc-auth-modal-title" className="text-lg font-semibold text-gray-900">
              VNC password required
            </h3>
            <p className="mt-2 text-sm text-gray-600">{vncAuthMessage}</p>
            <form className="mt-4 space-y-3" onSubmit={submitVncAuthModal}>
              <div>
                <label htmlFor="vnc-auth-password" className="block text-sm font-medium text-gray-700">
                  Password
                </label>
                <input
                  id="vnc-auth-password"
                  ref={vncAuthPasswordInputRef}
                  type="password"
                  autoComplete="off"
                  value={vncAuthPasswordInput}
                  onChange={(e) => {
                    setVncAuthPasswordInput(e.target.value);
                    setVncAuthFieldError('');
                  }}
                  className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:ring-blue-500"
                />
                {vncAuthFieldError && (
                  <p className="mt-1 text-sm text-red-600">{vncAuthFieldError}</p>
                )}
              </div>
              <div className="flex flex-wrap justify-end gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => disconnectVnc()}
                  className="rounded-md border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="rounded-md border border-transparent bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
                >
                  Continue
                </button>
              </div>
              <p className="text-xs text-gray-500">Press Escape to cancel and disconnect.</p>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default VncManager;
