/**
 * Local Nonogram puzzle generator matching puzzle-nonograms.com difficulty profile.
 *
 * Original site does NOT generate puzzles in the browser — "New Puzzle" calls
 * GET {baseUrl}/get?prevID=… and receives a precomputed { task, hashedSolution, … }.
 * Sampled live tasks are ~50% fill density with many multi-segment clue lines.
 *
 * This generator builds random ~50% solutions, derives clues the same task way,
 * and keeps only puzzles that logicSolve uniquely (no guessing required).
 */

import { cluesFromLine, CELL_FILLED } from './nonogramEngine';
import {
  logicSolve,
  gridsEqual,
  encodeTask,
  clueComplexity,
  refineLine,
  UNKNOWN,
} from './nonogramSolver';

/** Difficulty targets from live puzzle-nonograms.com samples (Jul 2026). */
const SIZE_PROFILE = {
  5: {
    density: 0.52,
    minMultiRatio: 0.25,
    minMaxClues: 2,
    minAvgClues: 1.2,
    minPasses: 2,
    maxAttempts: 200,
  },
  10: {
    density: 0.5,
    minMultiRatio: 0.5,
    minMaxClues: 2,
    minAvgClues: 1.5,
    minPasses: 3,
    maxAttempts: 160,
  },
  15: {
    density: 0.5,
    minMultiRatio: 0.75,
    minMaxClues: 3,
    minAvgClues: 2.2,
    minPasses: 4,
    maxAttempts: 120,
  },
  20: {
    density: 0.5,
    minMultiRatio: 0.85,
    minMaxClues: 4,
    minAvgClues: 2.8,
    minPasses: 5,
    maxAttempts: 80,
  },
  25: {
    density: 0.5,
    minMultiRatio: 0.9,
    minMaxClues: 5,
    minAvgClues: 3.4,
    minPasses: 6,
    maxAttempts: 50,
  },
};

function profileFor(size) {
  return (
    SIZE_PROFILE[size] || {
      density: 0.5,
      minMultiRatio: 0.5,
      minMaxClues: 2,
      minAvgClues: 1.5,
      minPasses: 3,
      maxAttempts: 100,
    }
  );
}

function rand() {
  return Math.random();
}

function randomInt(max) {
  return Math.floor(rand() * max);
}

/**
 * Build a noisy bitmap around target density, then lightly smooth so it is
 * closer to Conceptis-style organics than isolated salt-and-pepper.
 */
export function randomBitmap(width, height, density) {
  const grid = Array.from({ length: height }, () =>
    Array.from({ length: width }, () => (rand() < density ? 1 : 0))
  );

  // One smoothing pass: adopt majority of 3x3 (keeps density ≈ same).
  const next = cloneBitmap(grid);
  for (let r = 0; r < height; r += 1) {
    for (let c = 0; c < width; c += 1) {
      let sum = 0;
      let count = 0;
      for (let dr = -1; dr <= 1; dr += 1) {
        for (let dc = -1; dc <= 1; dc += 1) {
          const rr = r + dr;
          const cc = c + dc;
          if (rr < 0 || cc < 0 || rr >= height || cc >= width) continue;
          sum += grid[rr][cc];
          count += 1;
        }
      }
      next[r][c] = sum * 2 >= count ? 1 : 0;
    }
  }

  // Retarget density with random flips.
  return retargetDensity(next, density);
}

function cloneBitmap(grid) {
  return grid.map((row) => row.slice());
}

function retargetDensity(grid, density) {
  const height = grid.length;
  const width = grid[0].length;
  const total = width * height;
  const target = Math.round(total * density);
  let filled = 0;
  const cells = [];
  for (let r = 0; r < height; r += 1) {
    for (let c = 0; c < width; c += 1) {
      if (grid[r][c] === 1) filled += 1;
      cells.push([r, c]);
    }
  }

  // Shuffle
  for (let i = cells.length - 1; i > 0; i -= 1) {
    const j = randomInt(i + 1);
    const tmp = cells[i];
    cells[i] = cells[j];
    cells[j] = tmp;
  }

  if (filled < target) {
    for (let i = 0; i < cells.length && filled < target; i += 1) {
      const [r, c] = cells[i];
      if (grid[r][c] === 0) {
        grid[r][c] = 1;
        filled += 1;
      }
    }
  } else if (filled > target) {
    for (let i = 0; i < cells.length && filled > target; i += 1) {
      const [r, c] = cells[i];
      if (grid[r][c] === 1) {
        grid[r][c] = 0;
        filled -= 1;
      }
    }
  }
  return grid;
}

export function cluesFromBitmap(solution) {
  const height = solution.length;
  const width = solution[0].length;
  const rowClues = solution.map((row) => cluesFromLine(row.map((v) => (v ? CELL_FILLED : 0))));
  const colClues = [];
  for (let c = 0; c < width; c += 1) {
    colClues.push(cluesFromLine(solution.map((row) => (row[c] ? CELL_FILLED : 0))));
  }
  return { rowClues, colClues, width, height };
}

function meetsComplexity(rowClues, colClues, size) {
  const profile = profileFor(size);
  const stats = clueComplexity(rowClues, colClues);
  const lines = rowClues.length + colClues.length;
  const multiRatio = stats.multiClueLines / lines;
  return (
    stats.maxCluesOnLine >= profile.minMaxClues &&
    multiRatio >= profile.minMultiRatio &&
    stats.avgCluesPerLine >= profile.minAvgClues
  );
}

/** Count logic passes needed; too-few = trivially easy overlap puzzles. */
function countLogicPasses(rowClues, colClues) {
  const height = rowClues.length;
  const width = colClues.length;
  const grid = Array.from({ length: height }, () => Array(width).fill(UNKNOWN));
  let passes = 0;
  const maxPasses = width * height * 4;

  while (passes < maxPasses) {
    let changed = false;
    passes += 1;

    for (let r = 0; r < height; r += 1) {
      const result = refineLine(grid[r], rowClues[r]);
      if (result.contradiction) return -1;
      if (result.changed) {
        grid[r] = result.line;
        changed = true;
      }
    }

    for (let c = 0; c < width; c += 1) {
      const column = grid.map((row) => row[c]);
      const result = refineLine(column, colClues[c]);
      if (result.contradiction) return -1;
      if (result.changed) {
        for (let r = 0; r < height; r += 1) {
          grid[r][c] = result.line[r];
        }
        changed = true;
      }
    }

    if (!changed) break;
  }

  for (let r = 0; r < height; r += 1) {
    for (let c = 0; c < width; c += 1) {
      if (grid[r][c] === UNKNOWN) return -1;
    }
  }
  return passes;
}

function makePuzzleId(size) {
  return `${size}-gen-${Date.now().toString(36)}-${randomInt(1e6).toString(36)}`;
}

/**
 * Generate a single uniquely logic-solvable puzzle.
 */
export function generatePuzzle(width, height, options = {}) {
  const size = Math.max(width, height);
  const profile = profileFor(size);
  const density = options.density ?? profile.density;
  const maxAttempts = options.maxAttempts ?? profile.maxAttempts;

  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    const solution = randomBitmap(width, height, density);
    const { rowClues, colClues } = cluesFromBitmap(solution);

    if (!meetsComplexity(rowClues, colClues, size)) {
      continue;
    }

    const passes = countLogicPasses(rowClues, colClues);
    if (passes < profile.minPasses) {
      continue;
    }

    const solved = logicSolve(rowClues, colClues);
    if (!solved || !gridsEqual(solved, solution)) {
      continue;
    }

    return {
      id: makePuzzleId(size),
      name: `Puzzle ${width}×${height}`,
      width,
      height,
      rowClues,
      colClues,
      solution,
      task: encodeTask(rowClues, colClues),
      generated: true,
      attempt: attempt + 1,
      logicPasses: passes,
    };
  }

  // Soft fallback: accept logic-solvable even if complexity is a bit low.
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    const solution = randomBitmap(width, height, density);
    const { rowClues, colClues } = cluesFromBitmap(solution);
    const solved = logicSolve(rowClues, colClues);
    if (solved && gridsEqual(solved, solution)) {
      return {
        id: makePuzzleId(size),
        name: `Puzzle ${width}×${height}`,
        width,
        height,
        rowClues,
        colClues,
        solution,
        task: encodeTask(rowClues, colClues),
        generated: true,
        softFallback: true,
        attempt: attempt + 1,
      };
    }
  }

  return null;
}

export function generatePuzzleForSize(size) {
  return generatePuzzle(size, size);
}
