import { parseTask } from './nonogramSolver';

export const SPECIAL_MODES = ['daily', 'weekly', 'monthly'];

export const MODE_SIZE_PARAM = {
  weekly: 5,
  daily: 6,
  monthly: 7,
};

export const MODE_LABELS = {
  standard: 'Standard',
  daily: 'Daily',
  weekly: 'Weekly',
  monthly: 'Monthly',
};

export function isSpecialMode(mode) {
  return SPECIAL_MODES.includes(mode);
}

export function encodePassUrl(targetUrl) {
  return btoa(unescape(encodeURIComponent(targetUrl)));
}

/**
 * Build upstream puzzle-nonograms.com URL for a calendar mode.
 * @param {'daily'|'weekly'|'monthly'} mode
 * @param {string|null} date YYYY-MM-DD (optional)
 */
export function buildUpstreamPuzzleUrl(mode, date = null) {
  const size = MODE_SIZE_PARAM[mode];
  if (!size) {
    throw new Error(`Unknown special mode: ${mode}`);
  }
  let url = `https://www.puzzle-nonograms.com/?size=${size}`;
  if (date) {
    const normalized = mode === 'monthly' ? toMonthFirst(date) : date;
    url += `&date=${encodeURIComponent(normalized)}`;
  }
  return url;
}

export function buildUpstreamNewPuzzleUrl(prevId) {
  const cleaned = String(prevId).replace(/,/g, '');
  return `https://www.puzzle-nonograms.com/get?prevID=${encodeURIComponent(cleaned)}`;
}

function toMonthFirst(date) {
  const m = String(date).match(/^(\d{4})-(\d{2})/);
  if (!m) return date;
  return `${m[1]}-${m[2]}-01`;
}

function pick(regex, text) {
  const m = text.match(regex);
  return m ? m[1] : null;
}

/**
 * Parse puzzle-nonograms.com HTML page into a normalized puzzle object.
 */
export function parseNonogramPageHtml(html, { mode, sourceUrl, date } = {}) {
  if (!html || typeof html !== 'string') {
    throw new Error('Empty upstream response');
  }

  const task = pick(/var\s+task\s*=\s*'([^']+)'/, html)
    || pick(/var\s+task\s*=\s*"([^"]+)"/, html);
  const width = Number(pick(/puzzleWidth:\s*(\d+)/, html));
  const height = Number(pick(/puzzleHeight:\s*(\d+)/, html));
  const hashedSolution = pick(/hashedSolution:\s*'([a-f0-9]+)'/i, html)
    || pick(/hashedSolution:\s*"([a-f0-9]+)"/i, html);
  const specialDate = pick(/specialDate:\s*'([^']+)'/, html)
    || pick(/specialDate:\s*"([^"]+)"/, html)
    || date
    || null;

  let externalPuzzleId =
    pick(/Puzzle ID:\s*([\d,]+)/i, html)
    || pick(/id=["']puzzleID["'][^>]*>\s*([\d,]+)/i, html)
    || pick(/>([\d,]{3,})\s*<\/span>/i, html);

  if (!task || !width || !height) {
    throw new Error('Could not parse puzzle from upstream HTML');
  }

  const { rowClues, colClues } = parseTask(task, width, height);
  const idSuffix = specialDate || externalPuzzleId || Date.now();

  return {
    id: `${mode || 'special'}-${idSuffix}`,
    name: modeLabel(mode, specialDate),
    mode: mode || 'special',
    date: specialDate,
    width,
    height,
    rowClues,
    colClues,
    task,
    hashedSolution: hashedSolution || null,
    externalPuzzleId: externalPuzzleId ? String(externalPuzzleId).replace(/,/g, '') : null,
    sourceUrl: sourceUrl || null,
    sourced: 'upstream',
    solution: null,
  };
}

/**
 * Parse `/get?prevID=` JSON-ish or HTML-ish response.
 */
export function parseNonogramGetPayload(body, { mode, sourceUrl, date } = {}) {
  if (!body) {
    throw new Error('Empty /get response');
  }

  let data = body;
  if (typeof body === 'string') {
    const trimmed = body.trim();
    if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
      try {
        data = JSON.parse(trimmed);
      } catch {
        // Fall through to HTML parser
        return parseNonogramPageHtml(body, { mode, sourceUrl, date });
      }
    } else if (trimmed.includes('var task') || trimmed.includes('hashedSolution')) {
      return parseNonogramPageHtml(body, { mode, sourceUrl, date });
    } else {
      throw new Error('Unrecognized /get response');
    }
  }

  const task = data.task;
  const width = Number(data.puzzleWidth || data.width);
  const height = Number(data.puzzleHeight || data.height);
  if (!task || !width || !height) {
    throw new Error('Incomplete /get puzzle payload');
  }

  const { rowClues, colClues } = parseTask(task, width, height);
  const externalPuzzleId = data.id != null
    ? String(data.id).replace(/,/g, '')
    : (data.puzzleID != null ? String(data.puzzleID).replace(/,/g, '') : null);

  return {
    id: `${mode || 'special'}-new-${externalPuzzleId || Date.now()}`,
    name: modeLabel(mode, date),
    mode: mode || 'special',
    date: date || null,
    width,
    height,
    rowClues,
    colClues,
    task,
    hashedSolution: data.hashedSolution || data.solutionHash || null,
    externalPuzzleId,
    sourceUrl: sourceUrl || null,
    sourced: 'upstream-get',
    solution: null,
  };
}

function modeLabel(mode, date) {
  const base = MODE_LABELS[mode] || 'Special';
  return date ? `${base} Nonograms — ${date}` : `${base} Nonograms`;
}

export function todayISODate() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}
