const DB_NAME = 'hobapps-music-cache';
const DB_VERSION = 1;
const STORE_NAME = 'tracks';

function openDb() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB is not available in this browser'));
      return;
    }
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'path' });
        store.createIndex('cachedAt', 'cachedAt', { unique: false });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Failed to open music cache DB'));
  });
}

function idbRequest(mode, createRequest) {
  return openDb().then(
    (db) =>
      new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, mode);
        const store = tx.objectStore(STORE_NAME);
        let request;
        try {
          request = createRequest(store);
        } catch (err) {
          db.close();
          reject(err);
          return;
        }

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error || new Error('IndexedDB request failed'));
        tx.oncomplete = () => db.close();
        tx.onerror = () => {
          db.close();
          reject(tx.error || new Error('Music cache transaction failed'));
        };
        tx.onabort = () => {
          db.close();
          reject(tx.error || new Error('Music cache transaction aborted'));
        };
      })
  );
}

const musicCacheService = {
  async has(path) {
    if (!path) return false;
    const key = await idbRequest('readonly', (store) => store.getKey(path));
    return Boolean(key);
  },

  async hasMany(paths) {
    const unique = [...new Set((paths || []).filter(Boolean))];
    if (unique.length === 0) return [];
    const keys = await this.listPaths();
    const keySet = new Set(keys);
    return unique.filter((p) => keySet.has(p));
  },

  async get(path) {
    if (!path) return null;
    const row = await idbRequest('readonly', (store) => store.get(path));
    return row || null;
  },

  async put({ path, title, contentType, blob, size }) {
    if (!path || !blob) {
      throw new Error('path and blob are required');
    }
    const record = {
      path,
      title: title || path,
      contentType: contentType || blob.type || 'audio/mpeg',
      blob,
      size: size ?? blob.size ?? 0,
      cachedAt: new Date().toISOString(),
    };
    await idbRequest('readwrite', (store) => store.put(record));
    return record;
  },

  async remove(path) {
    if (!path) return false;
    await idbRequest('readwrite', (store) => store.delete(path));
    return true;
  },

  async listPaths() {
    const keys = await idbRequest('readonly', (store) => store.getAllKeys());
    return keys || [];
  },

  /**
   * Download a remote stream URL into IndexedDB.
   * Uses fetch so auth tokens in the URL query work.
   * Pass AbortSignal to cancel (e.g. on lock / track change) and avoid request spam.
   */
  async cacheFromUrl({ path, title, url, onProgress, signal }) {
    if (!path || !url) {
      throw new Error('path and url are required');
    }
    const response = await fetch(url, { signal });
    if (!response.ok) {
      throw new Error(`Download failed (HTTP ${response.status})`);
    }

    const contentType = response.headers.get('content-type') || 'audio/mpeg';
    const contentLength = Number(response.headers.get('content-length') || 0);

    let blob;
    if (response.body && onProgress && contentLength > 0) {
      const reader = response.body.getReader();
      const chunks = [];
      let received = 0;
      // eslint-disable-next-line no-constant-condition
      while (true) {
        // eslint-disable-next-line no-await-in-loop
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        received += value.byteLength || value.length || 0;
        onProgress(Math.min(100, Math.round((received / contentLength) * 100)));
      }
      blob = new Blob(chunks, { type: contentType });
    } else {
      blob = await response.blob();
      if (onProgress) onProgress(100);
    }

    await this.put({
      path,
      title,
      contentType: blob.type || contentType,
      blob,
      size: blob.size,
    });
    return blob;
  },
};

export default musicCacheService;
