export const CELL_EMPTY = 0;
export const CELL_FILLED = 1;
export const CELL_MARKED = 2;

export const DRAW_ROTATE = 'rotate';
export const DRAW_BLACK = 'black';
export const DRAW_CROSS = 'cross';
export const DRAW_BLANK = 'blank';

export const STANDARD_SIZES = [5, 10, 15, 20, 25];

export function createEmptyGrid(width, height) {
  return Array.from({ length: height }, () => Array(width).fill(CELL_EMPTY));
}

export function cloneGrid(grid) {
  return grid.map((row) => [...row]);
}

export function cluesFromLine(line) {
  const runs = [];
  let count = 0;
  for (const cell of line) {
    if (cell === 1 || cell === CELL_FILLED) {
      count += 1;
    } else if (count > 0) {
      runs.push(count);
      count = 0;
    }
  }
  if (count > 0) {
    runs.push(count);
  }
  return runs;
}

export function buildPuzzleFromPattern(id, name, pattern) {
  const solution = pattern.map((row) =>
    row.split('').map((ch) => (ch === '#' || ch === '1' ? 1 : 0))
  );
  const height = solution.length;
  const width = solution[0].length;
  const rowClues = solution.map((row) => cluesFromLine(row));
  const colClues = [];
  for (let c = 0; c < width; c += 1) {
    colClues.push(cluesFromLine(solution.map((row) => row[c])));
  }
  return { id, name, width, height, rowClues, colClues, solution };
}

export function getFilledRuns(cells) {
  const runs = [];
  let current = 0;
  for (const cell of cells) {
    if (cell === CELL_FILLED) {
      current += 1;
    } else if (current > 0) {
      runs.push(current);
      current = 0;
    }
  }
  if (current > 0) {
    runs.push(current);
  }
  return runs;
}

function runsMatch(clues, runs) {
  if (clues.length !== runs.length) {
    return false;
  }
  return clues.every((clue, index) => clue === runs[index]);
}

export function isLineComplete(cells, clues) {
  const runs = getFilledRuns(cells);
  if (!runsMatch(clues, runs)) {
    return false;
  }
  const expectedFilled = clues.reduce((sum, clue) => sum + clue, 0);
  const actualFilled = cells.filter((cell) => cell === CELL_FILLED).length;
  return actualFilled === expectedFilled;
}

export function getCompletedClueIndices(cells, clues) {
  if (clues.length === 0) {
    return cells.every((cell) => cell !== CELL_FILLED) ? [0] : [];
  }

  const completed = [];
  let clueIndex = 0;
  let runLength = 0;
  let inRun = false;

  for (let i = 0; i <= cells.length; i += 1) {
    const cell = i < cells.length ? cells[i] : CELL_MARKED;
    if (cell === CELL_FILLED) {
      runLength += 1;
      inRun = true;
    } else if (inRun) {
      if (clueIndex < clues.length && runLength === clues[clueIndex]) {
        completed.push(clueIndex);
        clueIndex += 1;
      }
      runLength = 0;
      inRun = false;
    }
  }

  return completed;
}

export function autoCrossLine(cells, clues) {
  if (!isLineComplete(cells, clues)) {
    return cells;
  }
  return cells.map((cell) => (cell === CELL_EMPTY ? CELL_MARKED : cell));
}

export function autoCrossGrid(grid, rowClues, colClues) {
  const next = cloneGrid(grid);
  let changed = false;

  for (let r = 0; r < grid.length; r += 1) {
    const crossed = autoCrossLine(next[r], rowClues[r]);
    if (crossed.some((cell, c) => cell !== next[r][c])) {
      next[r] = crossed;
      changed = true;
    }
  }

  const width = grid[0]?.length || 0;
  for (let c = 0; c < width; c += 1) {
    const column = next.map((row) => row[c]);
    const crossed = autoCrossLine(column, colClues[c]);
    if (crossed.some((cell, r) => cell !== next[r][c])) {
      for (let r = 0; r < next.length; r += 1) {
        next[r][c] = crossed[r];
      }
      changed = true;
    }
  }

  return { grid: next, changed };
}

export function checkWin(grid, solution) {
  for (let r = 0; r < solution.length; r += 1) {
    for (let c = 0; c < solution[0].length; c += 1) {
      const filled = grid[r][c] === CELL_FILLED;
      const shouldFill = solution[r][c] === 1;
      if (filled !== shouldFill) {
        return false;
      }
    }
  }
  return true;
}

/** Win when every row/col's filled runs exactly match clues (marks count as empty). */
export function checkWinByClues(grid, rowClues, colClues) {
  if (!grid?.length || !rowClues?.length || !colClues?.length) return false;
  if (grid.length !== rowClues.length || grid[0].length !== colClues.length) return false;

  for (let r = 0; r < rowClues.length; r += 1) {
    if (!isLineComplete(grid[r], rowClues[r])) return false;
  }
  for (let c = 0; c < colClues.length; c += 1) {
    const col = grid.map((row) => row[c]);
    if (!isLineComplete(col, colClues[c])) return false;
  }
  return true;
}

export function hasErrors(grid, solution) {
  if (!solution) return false;
  for (let r = 0; r < solution.length; r += 1) {
    for (let c = 0; c < solution[0].length; c += 1) {
      if (grid[r][c] === CELL_FILLED && solution[r][c] !== 1) {
        return true;
      }
    }
  }
  return false;
}

export function getNextRotateValue(current) {
  if (current === CELL_EMPTY) return CELL_FILLED;
  if (current === CELL_FILLED) return CELL_MARKED;
  return CELL_EMPTY;
}

export function getDrawValue(drawMode, currentCell, rotateTarget) {
  switch (drawMode) {
    case DRAW_BLACK:
      return CELL_FILLED;
    case DRAW_CROSS:
      return CELL_MARKED;
    case DRAW_BLANK:
      return CELL_EMPTY;
    case DRAW_ROTATE:
    default:
      return rotateTarget !== undefined ? rotateTarget : getNextRotateValue(currentCell);
  }
}

export function getMaxClueCount(clues) {
  return clues.reduce((max, line) => Math.max(max, line.length), 0);
}

export function formatTimer(seconds) {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
}

export function formatTimerPrecise(elapsedMs) {
  const totalSeconds = elapsedMs / 1000;
  const mins = Math.floor(totalSeconds / 60);
  const secs = totalSeconds % 60;
  const wholeSecs = Math.floor(secs);
  const centis = Math.round((secs - wholeSecs) * 100);
  return `${String(mins).padStart(2, '0')}:${String(wholeSecs).padStart(2, '0')}.${String(centis).padStart(2, '0')}`;
}

export function getDefaultCellSize(width, height, zoom = 1) {
  const maxDim = Math.max(width, height);
  let base = 34;
  if (maxDim >= 25) base = 22;
  else if (maxDim >= 20) base = 24;
  else if (maxDim > 15) base = 26;
  else if (maxDim > 10) base = 30;
  return Math.max(12, Math.round(base * zoom));
}

/** Suggested zoom so large boards stay readable on first open. */
export function getRecommendedZoom(width, height) {
  const maxDim = Math.max(width, height);
  if (maxDim >= 25) return 1.2;
  if (maxDim >= 20) return 1.1;
  if (maxDim >= 15) return 1.05;
  return 1;
}

export function diamondPattern(size) {
  const mid = Math.floor(size / 2);
  const rows = [];
  for (let r = 0; r < size; r += 1) {
    let row = '';
    for (let c = 0; c < size; c += 1) {
      const dist = Math.abs(r - mid) + Math.abs(c - mid);
      row += dist <= mid ? '#' : '.';
    }
    rows.push(row);
  }
  return rows;
}

export function hollowSquarePattern(size) {
  const rows = [];
  for (let r = 0; r < size; r += 1) {
    let row = '';
    for (let c = 0; c < size; c += 1) {
      const border = r === 0 || c === 0 || r === size - 1 || c === size - 1;
      const innerBorder = size > 4 && (r === 2 || c === 2 || r === size - 3 || c === size - 3);
      row += border || innerBorder ? '#' : '.';
    }
    rows.push(row);
  }
  return rows;
}
