import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import apiService from '../services/apiService';
import musicCacheService from '../services/musicCacheService';

const MUSIC_ROOT = 'Shares/HoBApps/Musics';
const DEFAULT_PLAYLIST_SLUG = 'hoatauphatgiao';
const SELECTED_PLAYLIST_KEY = 'hobapps_selected_music_playlist';

function playlistFolderPath(slug) {
  return `${MUSIC_ROOT}/${slug}`;
}

function formatPlaylistLabel(name) {
  if (!name) return 'Playlist';
  return name
    .replace(/[-_]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function readStoredPlaylistSlug() {
  try {
    const stored = localStorage.getItem(SELECTED_PLAYLIST_KEY);
    if (stored && !stored.includes('/') && !stored.includes('..')) {
      return stored;
    }
  } catch (_) {
    /* ignore */
  }
  return DEFAULT_PLAYLIST_SLUG;
}

const MediaPlayer = () => {
  const [currentTrack, setCurrentTrack] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [showPlaylist, setShowPlaylist] = useState(true);
  const [mediaType, setMediaType] = useState('audio'); // 'audio' or 'video'
  const [mediaError, setMediaError] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isShuffled, setIsShuffled] = useState(false);
  const [loopMode, setLoopMode] = useState('all'); // 'none', 'one', 'all' — default all for lock-screen playlists
  const [shuffledPlaylist, setShuffledPlaylist] = useState([]);
  const [playlist, setPlaylist] = useState([]);
  const [playlistLoading, setPlaylistLoading] = useState(true);
  const [playlistError, setPlaylistError] = useState(null);
  const [libraryPlaylists, setLibraryPlaylists] = useState([]);
  const [libraryLoading, setLibraryLoading] = useState(true);
  const [selectedPlaylistSlug, setSelectedPlaylistSlug] = useState(readStoredPlaylistSlug);
  const [cachedPaths, setCachedPaths] = useState(() => new Set());
  const [cachingPaths, setCachingPaths] = useState(() => new Set());
  const [cacheProgress, setCacheProgress] = useState({});
  const [playbackUrl, setPlaybackUrl] = useState('');
  const [playingFromCache, setPlayingFromCache] = useState(false);
  
  const audioRef = useRef(null);
  const videoRef = useRef(null);
  const progressRef = useRef(null);
  // Continue playback across track changes (next/prev/playlist/auto-advance)
  const shouldAutoplayRef = useRef(false);
  // Stable blob: URLs keyed by path — never revoke while the page is open (prevents iOS silent play)
  const blobUrlByPathRef = useRef(new Map());
  // Preloaded next track URL for iOS lock-screen advance (must play() inside ended handler)
  const nextReadyRef = useRef({ index: -1, path: null, url: null, fromCache: false });
  // Path whose URL was set imperatively — don't let resolve effect wipe it
  const imperativePathRef = useRef(null);
  // Last URL loaded into the <audio> element
  const loadedPlaybackUrlRef = useRef('');
  const volumeRef = useRef(volume);
  // Approximate "locked / backgrounded" — browsers do not expose a real lock API
  const isPageHiddenRef = useRef(
    typeof document !== 'undefined' ? document.visibilityState === 'hidden' : false
  );
  // Declared early — findNextCachedIndex / advanceToIndex read this at call time
  const cachedPathsRef = useRef(cachedPaths);
  const cachingPathsRef = useRef(cachingPaths);
  // Cancel in-flight cache downloads (stops unlock request spam)
  const prefetchAbortRef = useRef(null);
  const cacheAbortRef = useRef(null);
  // Ignore stale async advance results
  const advanceGenRef = useRef(0);
  // Gate network caching — iOS may keep visibility=visible while locked
  const allowNetworkCacheRef = useRef(true);

  const refreshCacheStatus = useCallback(async (tracks) => {
    try {
      const paths = (tracks || []).map((t) => t.path).filter(Boolean);
      const cached = await musicCacheService.hasMany(paths);
      setCachedPaths(new Set(cached));
    } catch (err) {
      console.error('Failed to read music cache status:', err);
    }
  }, []);

  const selectedPlaylistMeta =
    libraryPlaylists.find((p) => p.id === selectedPlaylistSlug) || null;
  const selectedPlaylistFolder =
    selectedPlaylistMeta?.path || playlistFolderPath(selectedPlaylistSlug);
  const selectedPlaylistLabel = formatPlaylistLabel(
    selectedPlaylistMeta?.name || selectedPlaylistSlug
  );

  const loadLibraryPlaylists = useCallback(async () => {
    setLibraryLoading(true);
    try {
      const folders = await apiService.getOcisPlaylists();
      const list = Array.isArray(folders) ? folders : [];
      setLibraryPlaylists(list);

      setSelectedPlaylistSlug((prev) => {
        if (list.some((p) => p.id === prev)) return prev;
        if (list.some((p) => p.id === DEFAULT_PLAYLIST_SLUG)) {
          try {
            localStorage.setItem(SELECTED_PLAYLIST_KEY, DEFAULT_PLAYLIST_SLUG);
          } catch (_) {
            /* ignore */
          }
          return DEFAULT_PLAYLIST_SLUG;
        }
        if (list.length > 0) {
          try {
            localStorage.setItem(SELECTED_PLAYLIST_KEY, list[0].id);
          } catch (_) {
            /* ignore */
          }
          return list[0].id;
        }
        return prev || DEFAULT_PLAYLIST_SLUG;
      });
    } catch (error) {
      console.error('Failed to load playlists:', error);
      setLibraryPlaylists([]);
      // Keep default slug so tracks can still load if music endpoint works
    } finally {
      setLibraryLoading(false);
    }
  }, []);

  const loadOcisPlaylist = useCallback(async (folderPath) => {
    const folder = folderPath || playlistFolderPath(DEFAULT_PLAYLIST_SLUG);
    setPlaylistLoading(true);
    setPlaylistError(null);
    // Stop current playback when switching folders
    shouldAutoplayRef.current = false;
    imperativePathRef.current = null;
    loadedPlaybackUrlRef.current = '';
    nextReadyRef.current = { index: -1, path: null, url: null, fromCache: false };
    if (audioRef.current) {
      try {
        audioRef.current.pause();
      } catch (_) {
        /* ignore */
      }
    }
    setIsPlaying(false);
    setPlaybackUrl('');
    setMediaError(null);

    try {
      const tracks = await apiService.getOcisMusic(folder);
      const mapped = (tracks || []).map((track) => ({
        id: track.id || track.path,
        title: track.title || track.path,
        artist: track.artist || 'HoB Apps',
        type: track.type || 'audio',
        path: track.path,
        url: apiService.getOcisStreamUrl(track.path),
        thumbnail: null,
      }));
      setPlaylist(mapped);
      setCurrentTrack(0);
      setIsShuffled(false);
      setShuffledPlaylist([]);
      setCurrentTime(0);
      setDuration(0);
      if (mapped.length > 0) {
        setMediaType(mapped[0].type || 'audio');
        setShowPlaylist(true);
      }
      if (mapped.length === 0) {
        setPlaylistError('No audio files found in this playlist folder.');
      }
      await refreshCacheStatus(mapped);
    } catch (error) {
      setPlaylist([]);
      setPlaylistError(
        error.message ||
          'Failed to load music from OCIS. Set OCIS_FILE_USER and OCIS_FILE_TOKEN in Profile → Personal Settings.'
      );
    } finally {
      setPlaylistLoading(false);
    }
  }, [refreshCacheStatus]);

  useEffect(() => {
    loadLibraryPlaylists();
  }, [loadLibraryPlaylists]);

  useEffect(() => {
    if (libraryLoading) return undefined;
    loadOcisPlaylist(playlistFolderPath(selectedPlaylistSlug));
    return undefined;
  }, [libraryLoading, selectedPlaylistSlug, loadOcisPlaylist]);

  const handleSelectLibraryPlaylist = (slug) => {
    if (!slug || slug === selectedPlaylistSlug) return;
    try {
      localStorage.setItem(SELECTED_PLAYLIST_KEY, slug);
    } catch (_) {
      /* ignore */
    }
    setSelectedPlaylistSlug(slug);
  };

  // Get current playlist (original or shuffled)
  const currentPlaylist = isShuffled ? shuffledPlaylist : playlist;
  const currentMedia = currentPlaylist[currentTrack] || null;

  const getStableBlobUrl = useCallback(async (path) => {
    if (!path) return null;
    const existing = blobUrlByPathRef.current.get(path);
    if (existing) return existing;
    try {
      const cached = await musicCacheService.get(path);
      if (cached?.blob) {
        const objectUrl = URL.createObjectURL(cached.blob);
        blobUrlByPathRef.current.set(path, objectUrl);
        return objectUrl;
      }
    } catch (err) {
      console.error('Failed to build blob URL:', err);
    }
    return null;
  }, []);

  // Prefer IndexedDB blob when cached; otherwise stream from OCIS
  useEffect(() => {
    let cancelled = false;

    const resolvePlaybackUrl = async () => {
      if (!currentMedia?.path) {
        if (!cancelled) {
          setPlaybackUrl('');
          setPlayingFromCache(false);
        }
        return;
      }

      // Imperative advance already set the correct URL for this path — do not clear/reload
      if (imperativePathRef.current === currentMedia.path) {
        return;
      }

      try {
        const objectUrl = await getStableBlobUrl(currentMedia.path);
        if (cancelled) return;
        if (objectUrl) {
          setPlaybackUrl(objectUrl);
          setPlayingFromCache(true);
          return;
        }
      } catch (err) {
        console.error('Failed to read cached track:', err);
      }

      if (!cancelled) {
        setPlaybackUrl(currentMedia.url || '');
        setPlayingFromCache(false);
      }
    };

    resolvePlaybackUrl();

    return () => {
      cancelled = true;
    };
  }, [currentMedia?.path, currentMedia?.url, getStableBlobUrl]);

  // Prefetch + warm blob for *next* track while current plays (required for iOS lock auto-advance).
  // Never assign a network URL into nextReady — ended→play() must be sync + blob-only.
  useEffect(() => {
    let cancelled = false;
    const list = currentPlaylist;
    if (!list.length || loopMode === 'one') return undefined;

    let nextIndex = currentTrack + 1;
    if (nextIndex >= list.length) {
      if (loopMode === 'all') nextIndex = 0;
      else return undefined;
    }

    const track = list[nextIndex];
    if (!track?.path) return undefined;

    // Abort any previous prefetch download
    if (prefetchAbortRef.current) {
      prefetchAbortRef.current.abort();
      prefetchAbortRef.current = null;
    }

    (async () => {
      let objectUrl = await getStableBlobUrl(track.path);

      // Only download while allowed — lock/background cannot finish usefully and spams on unlock
      const canDownload =
        allowNetworkCacheRef.current &&
        (typeof document === 'undefined' || document.visibilityState === 'visible');

      if (!objectUrl && track.url && canDownload && !cachingPathsRef.current.has(track.path)) {
        const ac = new AbortController();
        prefetchAbortRef.current = ac;
        try {
          cachingPathsRef.current = new Set(cachingPathsRef.current).add(track.path);
          setCachingPaths((prev) => new Set(prev).add(track.path));
          await musicCacheService.cacheFromUrl({
            path: track.path,
            title: track.title,
            url: track.url,
            signal: ac.signal,
          });
          if (!cancelled) {
            setCachedPaths((prev) => new Set(prev).add(track.path));
          }
          objectUrl = await getStableBlobUrl(track.path);
        } catch (err) {
          if (err?.name !== 'AbortError') {
            console.warn('Prefetch cache next track failed:', err);
          }
        } finally {
          if (prefetchAbortRef.current === ac) prefetchAbortRef.current = null;
          setCachingPaths((prev) => {
            const next = new Set(prev);
            next.delete(track.path);
            return next;
          });
          const nextCaching = new Set(cachingPathsRef.current);
          nextCaching.delete(track.path);
          cachingPathsRef.current = nextCaching;
        }
      }

      if (cancelled) return;

      // Warm blob into memory map even if already cached in IDB
      if (!objectUrl) {
        objectUrl = await getStableBlobUrl(track.path);
      }

      nextReadyRef.current = {
        index: nextIndex,
        path: track.path,
        url: objectUrl || '',
        fromCache: Boolean(objectUrl),
      };
    })();

    return () => {
      cancelled = true;
      if (prefetchAbortRef.current) {
        prefetchAbortRef.current.abort();
        prefetchAbortRef.current = null;
      }
    };
  }, [currentTrack, playlist, shuffledPlaylist, isShuffled, loopMode, getStableBlobUrl]);

  // Abort downloads when screen locks / tab hides (queued requests otherwise flood the server on unlock)
  useEffect(() => {
    const abortDownloads = () => {
      allowNetworkCacheRef.current = false;
      if (prefetchAbortRef.current) {
        prefetchAbortRef.current.abort();
        prefetchAbortRef.current = null;
      }
      if (cacheAbortRef.current) {
        cacheAbortRef.current.abort();
        cacheAbortRef.current = null;
      }
    };
    const allowDownloads = () => {
      allowNetworkCacheRef.current = document.visibilityState !== 'hidden';
    };
    const onVisibility = () => {
      if (document.visibilityState === 'hidden') abortDownloads();
      else allowDownloads();
    };
    document.addEventListener('visibilitychange', onVisibility);
    window.addEventListener('pagehide', abortDownloads);
    window.addEventListener('pageshow', allowDownloads);
    document.addEventListener('freeze', abortDownloads);
    document.addEventListener('resume', allowDownloads);
    return () => {
      document.removeEventListener('visibilitychange', onVisibility);
      window.removeEventListener('pagehide', abortDownloads);
      window.removeEventListener('pageshow', allowDownloads);
      document.removeEventListener('freeze', abortDownloads);
      document.removeEventListener('resume', allowDownloads);
    };
  }, []);

  useEffect(() => {
    return () => {
      blobUrlByPathRef.current.forEach((url) => {
        try {
          URL.revokeObjectURL(url);
        } catch (_) {
          /* ignore */
        }
      });
      blobUrlByPathRef.current.clear();
      prefetchAbortRef.current?.abort();
      cacheAbortRef.current?.abort();
    };
  }, []);

  const loopModeRef = useRef(loopMode);
  const currentTrackRef = useRef(currentTrack);
  const currentPlaylistRef = useRef(currentPlaylist);
  const cacheTrackIfNeededRef = useRef(null);

  useEffect(() => {
    loopModeRef.current = loopMode;
  }, [loopMode]);
  useEffect(() => {
    currentTrackRef.current = currentTrack;
  }, [currentTrack]);
  useEffect(() => {
    currentPlaylistRef.current = currentPlaylist;
  }, [currentPlaylist]);
  useEffect(() => {
    volumeRef.current = volume;
  }, [volume]);

  useEffect(() => {
    const syncHidden = () => {
      isPageHiddenRef.current = document.visibilityState === 'hidden';
    };
    const markHidden = () => {
      isPageHiddenRef.current = true;
    };
    syncHidden();
    document.addEventListener('visibilitychange', syncHidden);
    window.addEventListener('pagehide', markHidden);
    window.addEventListener('pageshow', syncHidden);
    document.addEventListener('freeze', markHidden);
    document.addEventListener('resume', syncHidden);
    return () => {
      document.removeEventListener('visibilitychange', syncHidden);
      window.removeEventListener('pagehide', markHidden);
      window.removeEventListener('pageshow', syncHidden);
      document.removeEventListener('freeze', markHidden);
      document.removeEventListener('resume', syncHidden);
    };
  }, []);

  const isPathCached = useCallback((path) => {
    return Boolean(
      path &&
        (cachedPathsRef.current.has(path) || blobUrlByPathRef.current.has(path))
    );
  }, []);

  /** Sync only — in-memory blob URLs (safe to play() inside ended on iOS). */
  const findNextWarmBlobIndex = useCallback((fromIndex) => {
    const list = currentPlaylistRef.current;
    if (!list.length) return -1;
    for (let n = 1; n <= list.length; n += 1) {
      const idx = (fromIndex + n) % list.length;
      const path = list[idx]?.path;
      if (path && blobUrlByPathRef.current.has(path)) return idx;
    }
    return -1;
  }, []);

  /** Next playlist index that is already in device cache (skips uncached). */
  const findNextCachedIndex = useCallback((fromIndex) => {
    const list = currentPlaylistRef.current;
    if (!list.length) return -1;
    for (let n = 1; n <= list.length; n += 1) {
      const idx = (fromIndex + n) % list.length;
      if (isPathCached(list[idx]?.path)) return idx;
    }
    return -1;
  }, [isPathCached]);

  /** Previous playlist index that is already in device cache. */
  const findPrevCachedIndex = useCallback((fromIndex) => {
    const list = currentPlaylistRef.current;
    if (!list.length) return -1;
    for (let n = 1; n <= list.length; n += 1) {
      const idx = (fromIndex - n + list.length) % list.length;
      if (isPathCached(list[idx]?.path)) return idx;
    }
    return -1;
  }, [isPathCached]);

  /**
   * Imperatively switch track + play in the same turn as a media event.
   * iOS lock screen: play() after any await is rejected — fromEnded must stay fully sync + blob-only.
   */
  const advanceToIndex = useCallback((index, { play = true, fromEnded = false, cacheOnly = false } = {}) => {
    const list = currentPlaylistRef.current;
    if (!list.length || index < 0 || index >= list.length) return;

    // Auto-advance always blob-only: iOS often keeps visibility=visible while locked,
    // and async IDB/network play() after ended is silent / spams streams on unlock.
    const requireCache = cacheOnly || fromEnded;
    let targetIndex = index;

    const applySync = (track, url, fromCache) => {
      if (!url) return false;
      const audio = audioRef.current;

      shouldAutoplayRef.current = play;
      imperativePathRef.current = track.path;

      setCurrentTrack(targetIndex);
      setMediaType(track.type || 'audio');
      setPlaybackUrl(url);
      setPlayingFromCache(fromCache);
      setCurrentTime(0);
      setMediaError(null);

      if (audio && (track.type || 'audio') === 'audio') {
        if (audio.src !== url) {
          audio.src = url;
        }
        loadedPlaybackUrlRef.current = url;
        audio.volume = volumeRef.current;
        audio.muted = false;
        if (play) {
          try {
            audio.currentTime = 0;
          } catch (_) {
            /* ignore */
          }
          const playPromise = audio.play();
          if (playPromise && typeof playPromise.then === 'function') {
            playPromise
              .then(() => setIsPlaying(true))
              .catch((err) => {
                console.error('Advance play failed:', err);
                setIsPlaying(false);
              });
          }
        } else {
          setIsPlaying(false);
        }
      }
      return true;
    };

    // --- Sync path for ended / lock-screen continuity ---
    if (fromEnded) {
      const ready = nextReadyRef.current;
      let url = null;

      if (ready.index === targetIndex && ready.fromCache && ready.url?.startsWith('blob:')) {
        url = ready.url;
      } else if (blobUrlByPathRef.current.has(list[targetIndex]?.path)) {
        url = blobUrlByPathRef.current.get(list[targetIndex].path);
      } else {
        const warm = findNextWarmBlobIndex(currentTrackRef.current);
        if (warm < 0) {
          setIsPlaying(false);
          shouldAutoplayRef.current = false;
          setMediaError(
            'Next track is not ready in memory cache. Keep the screen on until the next cloud fills, then lock.'
          );
          return;
        }
        targetIndex = warm;
        url = blobUrlByPathRef.current.get(list[warm].path);
      }

      const track = list[targetIndex];
      if (ready.index === targetIndex) {
        nextReadyRef.current = { index: -1, path: null, url: null, fromCache: false };
      }
      applySync(track, url, true);
      return;
    }

    if (requireCache && !isPathCached(list[targetIndex]?.path)) {
      const fallbackFrom = (targetIndex - 1 + list.length) % list.length;
      const resolved = findNextCachedIndex(fallbackFrom);
      if (resolved < 0) {
        setIsPlaying(false);
        shouldAutoplayRef.current = false;
        setMediaError('No cached tracks left to play.');
        return;
      }
      targetIndex = resolved;
    }

    const track = list[targetIndex];
    const ready = nextReadyRef.current;
    const useReady =
      ready.index === targetIndex &&
      Boolean(ready.url) &&
      (!requireCache || ready.fromCache);

    if (useReady) {
      applySync(track, ready.url, ready.fromCache);
      nextReadyRef.current = { index: -1, path: null, url: null, fromCache: false };
      return;
    }

    // Warm in-memory blob first (sync)
    const warmUrl = blobUrlByPathRef.current.get(track.path);
    if (warmUrl) {
      applySync(track, warmUrl, true);
      return;
    }

    const gen = ++advanceGenRef.current;
    getStableBlobUrl(track.path).then((objectUrl) => {
      if (gen !== advanceGenRef.current) return;
      if (objectUrl) {
        applySync(track, objectUrl, true);
      } else if (!requireCache) {
        applySync(track, track.url || '', false);
      } else {
        const resolved = findNextCachedIndex(targetIndex);
        if (resolved >= 0 && resolved !== targetIndex) {
          advanceToIndexRef.current(resolved, { play, cacheOnly: true });
        } else {
          setIsPlaying(false);
          setMediaError('No cached blob ready to play.');
        }
      }
    });
  }, [getStableBlobUrl, findNextCachedIndex, findNextWarmBlobIndex, isPathCached]);

  const advanceToIndexRef = useRef(advanceToIndex);
  const findNextCachedIndexRef = useRef(findNextCachedIndex);
  const findPrevCachedIndexRef = useRef(findPrevCachedIndex);
  const findNextWarmBlobIndexRef = useRef(findNextWarmBlobIndex);
  useEffect(() => {
    findNextCachedIndexRef.current = findNextCachedIndex;
  }, [findNextCachedIndex]);
  useEffect(() => {
    findPrevCachedIndexRef.current = findPrevCachedIndex;
  }, [findPrevCachedIndex]);
  useEffect(() => {
    findNextWarmBlobIndexRef.current = findNextWarmBlobIndex;
  }, [findNextWarmBlobIndex]);
  useEffect(() => {
    advanceToIndexRef.current = advanceToIndex;
  }, [advanceToIndex]);

  // Wire media element listeners; avoid pause/load when URL already loaded (iOS silence bug)
  useEffect(() => {
    const mediaElement = mediaType === 'audio' ? audioRef.current : videoRef.current;
    if (!mediaElement || !playbackUrl) {
      return undefined;
    }

    const alreadyLoaded = loadedPlaybackUrlRef.current === playbackUrl;
    const srcMatches =
      mediaElement.src === playbackUrl ||
      mediaElement.currentSrc === playbackUrl ||
      mediaElement.getAttribute('src') === playbackUrl;

    if (!alreadyLoaded && !srcMatches) {
      setMediaError(null);
      setIsLoading(true);
      setCurrentTime(0);
      setDuration(0);
      // Do not pause if we are mid imperative lock-screen play of this same URL
      mediaElement.pause();
      mediaElement.load();
      loadedPlaybackUrlRef.current = playbackUrl;
      mediaElement.volume = volumeRef.current;
      mediaElement.muted = false;
      if (!shouldAutoplayRef.current) {
        setIsPlaying(false);
      }
    } else {
      loadedPlaybackUrlRef.current = playbackUrl;
    }

    const updateTime = () => setCurrentTime(mediaElement.currentTime || 0);
    const updateDuration = () => {
      if (Number.isFinite(mediaElement.duration)) {
        setDuration(mediaElement.duration);
      }
      setIsLoading(false);
    };
    const handleEnded = () => {
      const mode = loopModeRef.current;
      const trackIndex = currentTrackRef.current;
      const list = currentPlaylistRef.current;
      setCurrentTime(0);
      if (mode === 'one') {
        shouldAutoplayRef.current = true;
        mediaElement.currentTime = 0;
        mediaElement.play().then(() => setIsPlaying(true)).catch(() => setIsPlaying(false));
        return;
      }
      if (mode === 'all' || trackIndex < list.length - 1) {
        let nextTrack = (trackIndex + 1) % list.length;
        // Prefer nextReady / warm blob; skip uncached (sync — required for iOS lock autoplay)
        const ready = nextReadyRef.current;
        if (!(ready.index === nextTrack && ready.fromCache && ready.url?.startsWith('blob:'))) {
          if (!blobUrlByPathRef.current.has(list[nextTrack]?.path)) {
            const warm = findNextWarmBlobIndexRef.current(trackIndex);
            if (warm < 0) {
              shouldAutoplayRef.current = false;
              setIsPlaying(false);
              setMediaError(
                'Next track is not ready offline. Keep the screen on until the next cloud fills, then lock.'
              );
              return;
            }
            nextTrack = warm;
          }
        }
        advanceToIndexRef.current(nextTrack, {
          play: true,
          fromEnded: true,
          cacheOnly: true,
        });
      } else {
        shouldAutoplayRef.current = false;
        setIsPlaying(false);
      }
    };
    const handleError = () => {
      const code = mediaElement.error?.code;
      const detail = mediaElement.error?.message || `code ${code || 'unknown'}`;
      console.error('Media error:', mediaElement.error);
      setMediaError(`Failed to load media (${detail}).`);
      setIsLoading(false);
      setIsPlaying(false);
    };
    const handleLoadStart = () => {
      setIsLoading(true);
      setMediaError(null);
    };
    const tryAutoplay = () => {
      if (!shouldAutoplayRef.current) return;
      mediaElement.volume = volumeRef.current;
      mediaElement.muted = false;
      mediaElement
        .play()
        .then(() => setIsPlaying(true))
        .catch((err) => {
          console.error('Autoplay failed:', err);
          setIsPlaying(false);
        });
    };
    const handleCanPlay = () => {
      setIsLoading(false);
      setMediaError(null);
      tryAutoplay();
    };
    const handlePlay = () => {
      setIsPlaying(true);
      shouldAutoplayRef.current = true;
    };
    const handlePause = () => setIsPlaying(false);

    mediaElement.addEventListener('timeupdate', updateTime);
    mediaElement.addEventListener('loadedmetadata', updateDuration);
    mediaElement.addEventListener('durationchange', updateDuration);
    mediaElement.addEventListener('ended', handleEnded);
    mediaElement.addEventListener('error', handleError);
    mediaElement.addEventListener('loadstart', handleLoadStart);
    mediaElement.addEventListener('canplay', handleCanPlay);
    mediaElement.addEventListener('play', handlePlay);
    mediaElement.addEventListener('pause', handlePause);

    return () => {
      mediaElement.removeEventListener('timeupdate', updateTime);
      mediaElement.removeEventListener('loadedmetadata', updateDuration);
      mediaElement.removeEventListener('durationchange', updateDuration);
      mediaElement.removeEventListener('ended', handleEnded);
      mediaElement.removeEventListener('error', handleError);
      mediaElement.removeEventListener('loadstart', handleLoadStart);
      mediaElement.removeEventListener('canplay', handleCanPlay);
      mediaElement.removeEventListener('play', handlePlay);
      mediaElement.removeEventListener('pause', handlePause);
    };
  }, [currentTrack, mediaType, playbackUrl]);

  // Lock-screen / Control Center (iOS + Android)
  useEffect(() => {
    if (!('mediaSession' in navigator) || !currentMedia) return undefined;

    try {
      navigator.mediaSession.metadata = new window.MediaMetadata({
        title: currentMedia.title || 'HoB Music',
        artist: currentMedia.artist || 'HoB Apps',
        album: 'HoB Apps Music',
      });
    } catch (err) {
      console.warn('MediaMetadata unavailable:', err);
    }

    const safeSet = (action, handler) => {
      try {
        navigator.mediaSession.setActionHandler(action, handler);
      } catch (_) {
        /* unsupported action */
      }
    };

    const resumeAudio = async () => {
      const audio = audioRef.current;
      if (!audio) return;
      shouldAutoplayRef.current = true;
      audio.volume = volumeRef.current;
      audio.muted = false;

      const list = currentPlaylistRef.current;
      const idx = currentTrackRef.current;
      const track = list[idx];

      // Ensure we play a blob when possible (stream URLs are silent / flaky on lock screen)
      if (track?.path) {
        let blobUrl = blobUrlByPathRef.current.get(track.path) || null;
        if (!blobUrl) {
          try {
            blobUrl = await getStableBlobUrl(track.path);
          } catch (_) {
            blobUrl = null;
          }
        }
        if (blobUrl && audio.src !== blobUrl) {
          audio.src = blobUrl;
          loadedPlaybackUrlRef.current = blobUrl;
          imperativePathRef.current = track.path;
          setPlaybackUrl(blobUrl);
          setPlayingFromCache(true);
        }
      }

      // iOS lock-screen Play after track ended → "playing" UI but silence unless we restart/advance
      const atEnd =
        audio.ended ||
        (Number.isFinite(audio.duration) && audio.duration > 0 && audio.currentTime >= audio.duration - 0.35);

      if (atEnd) {
        const mode = loopModeRef.current;
        if (mode === 'one' || list.length <= 1) {
          audio.currentTime = 0;
        } else if (mode === 'all' || idx < list.length - 1) {
          const warm = findNextWarmBlobIndexRef.current(idx);
          const next = warm >= 0 ? warm : findNextCachedIndexRef.current(idx);
          if (next < 0) {
            setIsPlaying(false);
            return;
          }
          // User gesture from lock screen — async blob load OK; still never stream
          advanceToIndexRef.current(next, {
            play: true,
            cacheOnly: true,
          });
          return;
        } else {
          audio.currentTime = 0;
        }
      }

      try {
        await audio.play();
        setIsPlaying(true);
      } catch (err) {
        console.error('Lock-screen play failed:', err);
        setIsPlaying(false);
      }
    };

    safeSet('play', () => {
      resumeAudio();
    });
    safeSet('pause', () => {
      shouldAutoplayRef.current = false;
      audioRef.current?.pause();
    });
    safeSet('previoustrack', () => {
      const list = currentPlaylistRef.current;
      if (!list.length) return;
      const idx = currentTrackRef.current;
      const prev = findPrevCachedIndexRef.current(idx);
      if (prev < 0) {
        const fallback = idx === 0 ? list.length - 1 : idx - 1;
        advanceToIndexRef.current(fallback, { play: true, cacheOnly: false });
        return;
      }
      advanceToIndexRef.current(prev, { play: true, cacheOnly: true });
    });
    safeSet('nexttrack', () => {
      const list = currentPlaylistRef.current;
      if (!list.length) return;
      const idx = currentTrackRef.current;
      const warm = findNextWarmBlobIndexRef.current(idx);
      const next = warm >= 0 ? warm : findNextCachedIndexRef.current(idx);
      if (next < 0) {
        advanceToIndexRef.current((idx + 1) % list.length, { play: true, cacheOnly: false });
        return;
      }
      advanceToIndexRef.current(next, { play: true, cacheOnly: true });
    });
    safeSet('seekto', (details) => {
      const audio = audioRef.current;
      if (audio && details.seekTime != null) {
        audio.currentTime = details.seekTime;
      }
    });

    return () => {
      ['play', 'pause', 'previoustrack', 'nexttrack', 'seekto'].forEach((action) => {
        try {
          navigator.mediaSession.setActionHandler(action, null);
        } catch (_) {
          /* ignore */
        }
      });
    };
  }, [currentMedia, getStableBlobUrl]);

  useEffect(() => {
    if (!('mediaSession' in navigator)) return;
    try {
      navigator.mediaSession.playbackState = isPlaying ? 'playing' : 'paused';
    } catch (_) {
      /* ignore */
    }
  }, [isPlaying]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.setAttribute('playsinline', '');
      audioRef.current.setAttribute('webkit-playsinline', '');
      audioRef.current.muted = false;
    }
  }, []);

  // Cleanup effect when component unmounts
  useEffect(() => {
    const audioElement = audioRef.current;
    const videoElement = videoRef.current;
    
    return () => {
      if (audioElement) {
        audioElement.pause();
        audioElement.removeAttribute('src');
        audioElement.load();
      }
      if (videoElement) {
        videoElement.pause();
        videoElement.src = '';
      }
    };
  }, []);

  useEffect(() => {
    cachedPathsRef.current = cachedPaths;
  }, [cachedPaths]);
  useEffect(() => {
    cachingPathsRef.current = cachingPaths;
  }, [cachingPaths]);

  const cacheTrackIfNeeded = useCallback(async (track, { silent = false } = {}) => {
    if (!track?.path || !track?.url) return false;
    if (cachedPathsRef.current.has(track.path) || cachingPathsRef.current.has(track.path)) {
      // Still warm in-memory blob for lock-screen sync advance
      await getStableBlobUrl(track.path);
      return false;
    }
    // Do not start new downloads while locked/hidden (they queue and spam the API on unlock)
    if (
      !allowNetworkCacheRef.current ||
      (typeof document !== 'undefined' && document.visibilityState === 'hidden')
    ) {
      return false;
    }

    const ac = new AbortController();
    cacheAbortRef.current = ac;

    setCachingPaths((prev) => new Set(prev).add(track.path));
    cachingPathsRef.current = new Set(cachingPathsRef.current).add(track.path);
    setCacheProgress((prev) => ({ ...prev, [track.path]: 0 }));
    try {
      await musicCacheService.cacheFromUrl({
        path: track.path,
        title: track.title,
        url: track.url,
        signal: ac.signal,
        onProgress: (pct) => {
          setCacheProgress((prev) => ({ ...prev, [track.path]: pct }));
        },
      });
      // Warm stable blob URL for lock-screen advance
      await getStableBlobUrl(track.path);
      setCachedPaths((prev) => new Set(prev).add(track.path));
      return true;
    } catch (err) {
      if (err?.name === 'AbortError') return false;
      console.error('Cache download failed:', err);
      if (!silent) {
        setMediaError(err.message || `Failed to cache "${track.title}"`);
      }
      return false;
    } finally {
      if (cacheAbortRef.current === ac) cacheAbortRef.current = null;
      setCachingPaths((prev) => {
        const next = new Set(prev);
        next.delete(track.path);
        return next;
      });
      const nextCaching = new Set(cachingPathsRef.current);
      nextCaching.delete(track.path);
      cachingPathsRef.current = nextCaching;
      setCacheProgress((prev) => {
        const next = { ...prev };
        delete next[track.path];
        return next;
      });
    }
  }, [getStableBlobUrl]);

  useEffect(() => {
    cacheTrackIfNeededRef.current = cacheTrackIfNeeded;
  }, [cacheTrackIfNeeded]);

  // Auto-cache current + warm blob while playing (visible only)
  useEffect(() => {
    if (!isPlaying || !currentMedia?.path) return undefined;
    if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
      return undefined;
    }
    cacheTrackIfNeeded(currentMedia, { silent: true });
    return undefined;
  }, [isPlaying, currentMedia?.path, cacheTrackIfNeeded]);

  const handleCacheDownload = async (track, event) => {
    if (event) {
      event.stopPropagation();
      event.preventDefault();
    }
    await cacheTrackIfNeeded(track, { silent: false });
  };

  const handleCacheRemove = async (track, event) => {
    if (event) {
      event.stopPropagation();
      event.preventDefault();
    }
    if (!track?.path || !cachedPaths.has(track.path)) return;
    try {
      await musicCacheService.remove(track.path);
      const blobUrl = blobUrlByPathRef.current.get(track.path);
      if (blobUrl) {
        URL.revokeObjectURL(blobUrl);
        blobUrlByPathRef.current.delete(track.path);
      }
      setCachedPaths((prev) => {
        const next = new Set(prev);
        next.delete(track.path);
        return next;
      });
      if (currentMedia?.path === track.path && playingFromCache) {
        imperativePathRef.current = null;
        loadedPlaybackUrlRef.current = '';
        setPlaybackUrl(track.url || '');
        setPlayingFromCache(false);
      }
    } catch (err) {
      console.error('Cache remove failed:', err);
      setMediaError(err.message || `Failed to remove "${track.title}" from cache`);
    }
  };

  const handleCacheAll = async (event) => {
    if (event) {
      event.stopPropagation();
      event.preventDefault();
    }
    const missing = currentPlaylist.filter((t) => t.path && !cachedPaths.has(t.path));
    for (const track of missing) {
      // Sequential to avoid flooding OCIS / browser memory
      // eslint-disable-next-line no-await-in-loop
      await cacheTrackIfNeeded(track, { silent: false });
    }
  };

  const handlePlayPause = async () => {
    const mediaElement = mediaType === 'audio' ? audioRef.current : videoRef.current;
    
    if (!mediaElement) return;
    
    try {
      if (isPlaying) {
        shouldAutoplayRef.current = false;
        mediaElement.pause();
      } else {
        shouldAutoplayRef.current = true;
        await mediaElement.play();
      }
    } catch (error) {
      console.error('Media playback error:', error);
      setMediaError(error?.message || 'Playback failed. Click play again after the track loads.');
      setIsPlaying(false);
    }
  };

  const selectTrack = (index, { autoplay = true } = {}) => {
    if (index < 0 || index >= currentPlaylist.length) return;
    advanceToIndex(index, { play: autoplay });
  };

  const handleNext = () => {
    if (currentPlaylist.length === 0) return;
    const nextTrack = (currentTrack + 1) % currentPlaylist.length;
    advanceToIndex(nextTrack, { play: true });
  };

  const handlePrevious = () => {
    if (currentPlaylist.length === 0) return;
    const prevTrack = currentTrack === 0 ? currentPlaylist.length - 1 : currentTrack - 1;
    advanceToIndex(prevTrack, { play: true });
  };

  const handleSeek = (e) => {
    const mediaElement = mediaType === 'audio' ? audioRef.current : videoRef.current;
    const rect = progressRef.current.getBoundingClientRect();
    const percent = (e.clientX - rect.left) / rect.width;
    const newTime = percent * duration;
    mediaElement.currentTime = newTime;
    setCurrentTime(newTime);
  };

  const handleVolumeChange = (e) => {
    const newVolume = parseFloat(e.target.value);
    setVolume(newVolume);
    if (audioRef.current) audioRef.current.volume = newVolume;
    if (videoRef.current) videoRef.current.volume = newVolume;
  };

  const formatTime = (time) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  // Shuffle playlist function
  const handleShuffle = () => {
    if (playlist.length === 0) return;
    const keepPlaying = isPlaying || shouldAutoplayRef.current;
    shouldAutoplayRef.current = keepPlaying;
    if (isShuffled) {
      // Return to original order
      setIsShuffled(false);
      setCurrentTrack(0);
      setMediaType(playlist[0].type);
    } else {
      // Create shuffled playlist
      const shuffled = [...playlist].sort(() => Math.random() - 0.5);
      setShuffledPlaylist(shuffled);
      setIsShuffled(true);
      setCurrentTrack(0);
      setMediaType(shuffled[0].type);
    }
    setCurrentTime(0);
  };

  // Toggle loop mode
  const handleLoopToggle = () => {
    switch (loopMode) {
      case 'none':
        setLoopMode('all');
        break;
      case 'all':
        setLoopMode('one');
        break;
      case 'one':
        setLoopMode('none');
        break;
      default:
        setLoopMode('none');
    }
  };

  // Get loop mode icon
  const getLoopIcon = () => {
    switch (loopMode) {
      case 'none':
        return (
          <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 4V1L8 5l4 4V6c3.31 0 6 2.69 6 6 0 1.01-.25 1.97-.7 2.8l1.46 1.46C19.54 15.03 20 13.57 20 12c0-4.42-3.58-8-8-8zm0 14c-3.31 0-6-2.69-6-6 0-1.01.25-1.97.7-2.8L5.24 7.74C4.46 8.97 4 10.43 4 12c0 4.42 3.58 8 8 8v3l4-4-4-4v3z"/>
          </svg>
        );
      case 'all':
        return (
          <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 4V1L8 5l4 4V6c3.31 0 6 2.69 6 6 0 1.01-.25 1.97-.7 2.8l1.46 1.46C19.54 15.03 20 13.57 20 12c0-4.42-3.58-8-8-8zm0 14c-3.31 0-6-2.69-6-6 0-1.01.25-1.97.7-2.8L5.24 7.74C4.46 8.97 4 10.43 4 12c0 4.42 3.58 8 8 8v3l4-4-4-4v3z"/>
          </svg>
        );
      case 'one':
        return (
          <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 4V1L8 5l4 4V6c3.31 0 6 2.69 6 6 0 1.01-.25 1.97-.7 2.8l1.46 1.46C19.54 15.03 20 13.57 20 12c0-4.42-3.58-8-8-8zm0 14c-3.31 0-6-2.69-6-6 0-1.01.25-1.97.7-2.8L5.24 7.74C4.46 8.97 4 10.43 4 12c0 4.42 3.58 8 8 8v3l4-4-4-4v3z"/>
            <circle cx="12" cy="12" r="3"/>
          </svg>
        );
      default:
        return null;
    }
  };

  // Get loop mode tooltip
  const getLoopTooltip = () => {
    switch (loopMode) {
      case 'none':
        return 'No Loop';
      case 'all':
        return 'Loop All';
      case 'one':
        return 'Loop One';
      default:
        return 'No Loop';
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white p-6">
      <div className="max-w-4xl mx-auto">
                 {/* Header */}
         <div className="text-center mb-8">
           <h1 className="text-4xl font-bold mb-2">Media Player</h1>
           <p className="text-gray-400">
             OCIS library <span className="text-gray-300">Shares / HoBApps / Musics</span>
             {selectedPlaylistSlug ? (
               <>
                 {' '}
                 / <span className="text-white">{selectedPlaylistLabel}</span>
               </>
             ) : null}
           </p>

           <div className="mt-4 p-4 bg-blue-900 bg-opacity-20 border border-blue-700 rounded-lg max-w-2xl mx-auto text-left">
             <div className="flex flex-col sm:flex-row sm:items-center gap-3">
               <label className="text-blue-100 text-sm font-medium whitespace-nowrap" htmlFor="ocis-playlist-select">
                 Playlist
               </label>
               <select
                 id="ocis-playlist-select"
                 value={selectedPlaylistSlug}
                 disabled={libraryLoading || libraryPlaylists.length === 0}
                 onChange={(e) => handleSelectLibraryPlaylist(e.target.value)}
                 className="flex-1 bg-gray-800 border border-blue-700 rounded-lg px-3 py-2 text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
               >
                 {libraryPlaylists.length === 0 ? (
                   <option value={selectedPlaylistSlug}>
                     {libraryLoading ? 'Loading playlists…' : formatPlaylistLabel(selectedPlaylistSlug)}
                   </option>
                 ) : (
                   libraryPlaylists.map((pl) => (
                     <option key={pl.id} value={pl.id}>
                       {formatPlaylistLabel(pl.name || pl.id)}
                     </option>
                   ))
                 )}
               </select>
             </div>
             <p className="mt-3 text-blue-200 text-xs">
               Each subfolder under <code className="text-blue-100">Shares/HoBApps/Musics</code> is a playlist.
               Uses <code className="text-blue-100">OCIS_FILE_USER</code> / <code className="text-blue-100">OCIS_FILE_TOKEN</code>.
             </p>
             <div className="mt-3 flex flex-wrap items-center gap-3 text-xs">
               <button
                 type="button"
                 onClick={() => {
                   loadLibraryPlaylists();
                   loadOcisPlaylist(selectedPlaylistFolder);
                 }}
                 className="px-3 py-1.5 rounded bg-blue-700 hover:bg-blue-600 text-white"
               >
                 Reload
               </button>
               <Link to="/profile" className="px-3 py-1.5 rounded bg-gray-700 hover:bg-gray-600 text-white">
                 Open Personal Settings
               </Link>
             </div>
           </div>

           {playlistLoading && (
             <p className="mt-4 text-blue-300 text-sm">Loading tracks from {selectedPlaylistLabel}…</p>
           )}
           {playlistError && (
             <div className="mt-4 p-3 bg-red-900 bg-opacity-30 border border-red-700 rounded-lg max-w-2xl mx-auto text-red-200 text-sm">
               {playlistError}
             </div>
           )}
         </div>

        {!playlistLoading && currentPlaylist.length === 0 ? (
          <div className="bg-gray-800 rounded-lg p-8 text-center text-gray-300">
            <p className="mb-4">No tracks to play.</p>
            <p className="text-sm text-gray-400">
              Add OCIS credentials in Profile → Personal Settings, then reload.
            </p>
          </div>
        ) : currentMedia ? (
        <>
        {/* Media Display */}
        <div className="bg-gray-800 rounded-lg p-6 mb-6">
          {mediaType === 'video' ? (
                         <video
               ref={videoRef}
               className="w-full rounded-lg mb-4"
               poster={currentMedia.thumbnail || undefined}
               controls={false}
               playsInline
               onError={(e) => {
                 console.error('Video loading error:', e);
                 // Handle video loading errors gracefully
               }}
               onLoadStart={() => {
                 // Reset state when new video starts loading
                 setCurrentTime(0);
                 setDuration(0);
               }}
             >
               <source src={currentMedia.url} type="video/mp4" />
               Your browser does not support the video tag.
             </video>
          ) : (
            <div className="text-center mb-4">
              <div className="w-64 h-64 mx-auto bg-gradient-to-br from-blue-600 to-purple-600 rounded-lg flex items-center justify-center mb-4">
                <svg className="w-32 h-32 text-white" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/>
                </svg>
              </div>
            </div>
          )}

                     {/* Track Info */}
           <div className="text-center mb-6">
             <h2 className="text-2xl font-bold mb-2">{currentMedia.title}</h2>
             <p className="text-gray-400">{currentMedia.artist}</p>
             <p className="text-sm text-gray-500 mt-1">
               {mediaType === 'audio' ? 'Audio Track' : 'Video'} • {currentTrack + 1} of {currentPlaylist.length}
               {playingFromCache && <span className="text-emerald-400 ml-2">Cached</span>}
               {!playingFromCache && currentMedia?.path && (
                 <span className="text-amber-400 ml-2">Streaming</span>
               )}
               {isShuffled && <span className="text-green-400 ml-2">Shuffled</span>}
               {loopMode !== 'none' && (
                 <span className="text-blue-400 ml-2">
                   {loopMode === 'all' ? 'Loop All' : 'Loop One'}
                 </span>
               )}
             </p>
             
             {/* Loading and Error States */}
             {isLoading && (
               <div className="mt-3 flex items-center justify-center space-x-2 text-blue-400">
                 <svg className="w-4 h-4 animate-spin" fill="currentColor" viewBox="0 0 24 24">
                   <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8z"/>
                   <path d="M12 4v2.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                 </svg>
                 <span className="text-sm">Loading media...</span>
               </div>
             )}
             
             {mediaError && (
               <div className="mt-3 p-3 bg-red-900 bg-opacity-20 border border-red-700 rounded-lg">
                 <div className="flex items-center space-x-2 text-red-400">
                   <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                     <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/>
                   </svg>
                   <span className="text-sm font-medium">{mediaError}</span>
                 </div>
                 <p className="text-xs text-red-300 mt-1">
                   Try selecting a different track from the playlist below.
                 </p>
               </div>
             )}
           </div>

                     {/* Progress Bar */}
           <div className="mb-4">
             <div 
               ref={progressRef}
               className={`w-full rounded-full h-2 relative ${
                 mediaError || isLoading 
                   ? 'bg-gray-700 cursor-not-allowed' 
                   : 'bg-gray-600 cursor-pointer'
               }`}
               onClick={mediaError || isLoading ? undefined : handleSeek}
             >
               <div 
                 className="bg-blue-500 h-2 rounded-full transition-all duration-300"
                 style={{ width: `${(currentTime / duration) * 100}%` }}
               />
             </div>
             <div className="flex justify-between text-sm text-gray-400 mt-2">
               <span>{formatTime(currentTime)}</span>
               <span>{formatTime(duration)}</span>
             </div>
           </div>

                     {/* Controls */}
           <div className="flex items-center justify-center space-x-6 mb-6">
             <button
               onClick={handlePrevious}
               disabled={isLoading}
               className={`p-3 rounded-full transition-colors ${
                 isLoading 
                   ? 'bg-gray-500 cursor-not-allowed' 
                   : 'bg-gray-700 hover:bg-gray-600'
               }`}
             >
               <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                 <path d="M6 6h2v12H6zm3.5 6l8.5 6V6z"/>
               </svg>
             </button>

             <button
               onClick={handlePlayPause}
               disabled={isLoading || mediaError}
               className={`p-4 rounded-full transition-colors ${
                 isLoading || mediaError 
                   ? 'bg-gray-500 cursor-not-allowed' 
                   : 'bg-blue-600 hover:bg-blue-700'
               }`}
             >
               {isLoading ? (
                 <svg className="w-8 h-8 animate-spin" fill="currentColor" viewBox="0 0 24 24">
                   <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8z"/>
                   <path d="M12 4v2.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                 </svg>
               ) : isPlaying ? (
                 <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24">
                   <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/>
                 </svg>
               ) : (
                 <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24">
                   <path d="M8 5v14l11-7z"/>
                 </svg>
               )}
             </button>

             <button
               onClick={handleNext}
               disabled={isLoading}
               className={`p-3 rounded-full transition-colors ${
                 isLoading 
                   ? 'bg-gray-500 cursor-not-allowed' 
                   : 'bg-gray-700 hover:bg-gray-600'
               }`}
             >
               <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                 <path d="M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z"/>
               </svg>
             </button>
           </div>

           {/* Shuffle and Loop Controls */}
           <div className="flex items-center justify-center space-x-4 mb-6">
             <button
               onClick={handleShuffle}
               disabled={isLoading}
               className={`p-3 rounded-lg transition-colors flex items-center space-x-2 ${
                 isLoading 
                   ? 'bg-gray-500 cursor-not-allowed' 
                   : isShuffled 
                     ? 'bg-green-600 hover:bg-green-700' 
                     : 'bg-gray-700 hover:bg-gray-600'
               }`}
               title={isShuffled ? 'Shuffle On' : 'Shuffle Off'}
             >
               <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                 <path d="M10.59 9.17L5.41 4 4 5.41l5.17 5.17 1.42-1.41zM14.5 4l2.04 2.04L4 18.59 5.41 20 17.96 7.04 20 9.5V4h-5.5zm.33 9.41l-1.41 1.41 3.13 3.13L14.5 20H20v-5.5l-2.04 2.04-3.13-3.13z"/>
               </svg>
               <span className="text-sm font-medium">Shuffle</span>
             </button>

             <button
               onClick={handleLoopToggle}
               disabled={isLoading}
               className={`p-3 rounded-lg transition-colors flex items-center space-x-2 ${
                 isLoading 
                   ? 'bg-gray-500 cursor-not-allowed' 
                   : loopMode !== 'none' 
                     ? 'bg-blue-600 hover:bg-blue-700' 
                     : 'bg-gray-700 hover:bg-gray-600'
               }`}
               title={getLoopTooltip()}
             >
               {getLoopIcon()}
               <span className="text-sm font-medium">
                 {loopMode === 'none' ? 'No Loop' : loopMode === 'all' ? 'Loop All' : 'Loop One'}
               </span>
             </button>
           </div>

          {/* Volume Control */}
          <div className="flex items-center justify-center space-x-4">
            <svg className="w-5 h-5 text-gray-400" fill="currentColor" viewBox="0 0 24 24">
              <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
            </svg>
            <input
              type="range"
              min="0"
              max="1"
              step="0.1"
              value={volume}
              onChange={handleVolumeChange}
              className="w-24 h-2 bg-gray-600 rounded-lg appearance-none cursor-pointer"
            />
            <span className="text-sm text-gray-400 w-8">{Math.round(volume * 100)}%</span>
          </div>
        </div>

        {/* Playlist Toggle */}
        <div className="text-center mb-4">
          <button
            onClick={() => setShowPlaylist(!showPlaylist)}
            className="bg-gray-700 hover:bg-gray-600 px-6 py-2 rounded-lg transition-colors flex items-center space-x-2 mx-auto"
          >
            <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
              <path d="M3 13h2v-2H3v2zm0 4h2v-2H3v2zm0-8h2V7H3v2zm4 4h14v-2H7v2zm0 4h14v-2H7v2zM7 7v2h14V7H7z"/>
            </svg>
            <span>{showPlaylist ? 'Hide' : 'Show'} Playlist</span>
          </button>
        </div>

                 {/* Playlist */}
         {showPlaylist && (
           <div className="bg-gray-800 rounded-lg p-6">
             <div className="flex items-center justify-between mb-4 gap-3 flex-wrap">
               <h3 className="text-xl font-bold">
                 Tracks
                 <span className="ml-2 text-sm font-normal text-gray-400">
                   {selectedPlaylistLabel}
                 </span>
               </h3>
               <div className="flex items-center space-x-3 text-sm">
                 <span className="text-gray-400">
                   {cachedPaths.size} cached
                 </span>
                 <button
                   type="button"
                   onClick={handleCacheAll}
                   className="px-3 py-1.5 rounded bg-emerald-700 hover:bg-emerald-600 text-white text-xs"
                   title="Download all uncached tracks"
                 >
                   Cache all
                 </button>
                 {isShuffled && (
                   <span className="text-green-400 flex items-center space-x-1">
                     <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
                       <path d="M10.59 9.17L5.41 4 4 5.41l5.17 5.17 1.42-1.41zM14.5 4l2.04 2.04L4 18.59 5.41 20 17.96 7.04 20 9.5V4h-5.5zm.33 9.41l-1.41 1.41 3.13 3.13L14.5 20H20v-5.5l-2.04 2.04-3.13-3.13z"/>
                     </svg>
                     <span>Shuffled</span>
                   </span>
                 )}
                 {loopMode !== 'none' && (
                   <span className="text-blue-400 flex items-center space-x-1">
                     {getLoopIcon()}
                     <span>{loopMode === 'all' ? 'Loop All' : 'Loop One'}</span>
                   </span>
                 )}
               </div>
             </div>
             <div className="space-y-2">
               {currentPlaylist.map((track, index) => {
                 const isCached = cachedPaths.has(track.path);
                 const isCaching = cachingPaths.has(track.path);
                 const progress = cacheProgress[track.path];
                 return (
                <div
                  key={track.id}
                  onClick={() => selectTrack(index, { autoplay: true })}
                  className={`flex items-center space-x-3 p-3 rounded-lg cursor-pointer transition-colors ${
                    index === currentTrack 
                      ? 'bg-blue-600 text-white' 
                      : 'bg-gray-700 hover:bg-gray-600'
                  }`}
                >
                  <div className="w-10 h-10 bg-gray-600 rounded-lg flex items-center justify-center flex-shrink-0">
                    {isCached ? (
                      <svg className="w-5 h-5 text-emerald-300" fill="currentColor" viewBox="0 0 24 24" title="Cached">
                        <path d="M19.35 10.04C18.67 6.59 15.64 4 12 4 9.11 4 6.6 5.64 5.35 8.04 2.34 8.36 0 10.91 0 14c0 3.31 2.69 6 6 6h13c2.76 0 5-2.24 5-5 0-2.64-2.05-4.78-4.65-4.96z"/>
                      </svg>
                    ) : (
                      <svg className="w-5 h-5 text-gray-300" fill="currentColor" viewBox="0 0 24 24" title="Not cached">
                        <path d="M19.35 10.04C18.67 6.59 15.64 4 12 4 9.11 4 6.6 5.64 5.35 8.04 2.34 8.36 0 10.91 0 14c0 3.31 2.69 6 6 6h13c2.76 0 5-2.24 5-5 0-2.64-2.05-4.78-4.65-4.96zM19 18H6c-2.21 0-4-1.79-4-4s1.79-4 4-4h.71C7.37 7.69 9.48 6 12 6c3.04 0 5.5 2.46 5.5 5.5v.5H19c1.66 0 3 1.34 3 3s-1.34 3-3 3z"/>
                      </svg>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className="font-medium truncate">{track.title}</h4>
                    <p className={`text-sm truncate ${index === currentTrack ? 'text-blue-100' : 'text-gray-400'}`}>
                      {isCaching
                        ? `Caching${typeof progress === 'number' ? ` ${progress}%` : '…'}`
                        : isCached
                          ? 'On device cache'
                          : 'Stream online'}
                    </p>
                  </div>
                  <div className="flex items-center space-x-1 flex-shrink-0" onClick={(e) => e.stopPropagation()}>
                    {isCaching ? (
                      <span className="p-2 text-amber-300" title="Downloading…">
                        <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z" />
                        </svg>
                      </span>
                    ) : isCached ? (
                      <button
                        type="button"
                        onClick={(e) => handleCacheRemove(track, e)}
                        className={`p-2 rounded hover:bg-black hover:bg-opacity-20 ${
                          index === currentTrack ? 'text-white' : 'text-red-300 hover:text-red-200'
                        }`}
                        title="Remove from cache"
                      >
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                          <path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/>
                        </svg>
                      </button>
                    ) : (
                      <button
                        type="button"
                        onClick={(e) => handleCacheDownload(track, e)}
                        className={`p-2 rounded hover:bg-black hover:bg-opacity-20 ${
                          index === currentTrack ? 'text-white' : 'text-emerald-300 hover:text-emerald-200'
                        }`}
                        title="Download to cache"
                      >
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                          <path d="M5 20h14v-2H5v2zM19 9h-4V3H9v6H5l7 7 7-7z"/>
                        </svg>
                      </button>
                    )}
                  </div>
                </div>
                 );
               })}
            </div>
          </div>
        )}

        {/* Hidden Audio Element for Background Playback */}
        <audio
          ref={audioRef}
          src={mediaType === 'audio' ? playbackUrl || undefined : undefined}
          preload="auto"
          playsInline
          muted={false}
          webkit-playsinline="true"
          onError={() => {
            // Handled by the media element effect listener
          }}
          onLoadStart={() => {
            setCurrentTime(0);
            setDuration(0);
          }}
        />

        {/* PWA Background Audio Info */}
        <div className="mt-8 text-center">
          <div className="bg-blue-900 bg-opacity-20 border border-blue-700 rounded-lg p-4">
            <h3 className="text-lg font-semibold mb-2">Offline cache &amp; iPhone lock screen</h3>
            <p className="text-gray-300 text-sm">
              Play unlocked until the <strong>next</strong> row shows a filled cloud (blob ready).
              Auto-next on lock only works from that in-memory cache — not from the network.
            </p>
            <div className="mt-3 text-xs text-gray-400 space-y-1">
              <p>Use Cache all before locking for a continuous offline playlist</p>
              <p>Downloads pause while locked so unlock does not flood the server</p>
            </div>
          </div>
        </div>
        </>
        ) : null}
      </div>
    </div>
  );
};

export default MediaPlayer;
