/**
 * Nonogram line logic solver (Conceptis-style deductions).
 * Used to validate that generated puzzles are uniquely solvable by logic.
 */

export const UNKNOWN = -1;
export const EMPTY = 0;
export const FILLED = 1;

/** Enumerate valid 0/1 fillings of a line for the given clues. */
export function enumerateLinePlacements(length, clues, limit = 8000) {
  if (!clues || clues.length === 0) {
    return [Array(length).fill(EMPTY)];
  }

  const placements = [];
  const minNeed = clues.reduce((sum, run) => sum + run, 0) + (clues.length - 1);
  if (minNeed > length) {
    return placements;
  }

  const rec = (clueIndex, start, line) => {
    if (placements.length >= limit) {
      return;
    }
    if (clueIndex === clues.length) {
      const complete = line.map((cell) => (cell === undefined ? EMPTY : cell));
      placements.push(complete);
      return;
    }

    const run = clues[clueIndex];
    const remaining = clues.slice(clueIndex + 1);
    const minRest = remaining.reduce((sum, value) => sum + value, 0) + remaining.length;
    const maxStart = length - run - minRest;

    for (let pos = start; pos <= maxStart; pos += 1) {
      const next = line.slice();
      let fits = true;
      for (let i = 0; i < run; i += 1) {
        if (next[pos + i] === EMPTY) {
          fits = false;
          break;
        }
        next[pos + i] = FILLED;
      }
      if (!fits) continue;

      if (clueIndex < clues.length - 1) {
        if (next[pos + run] === FILLED) continue;
        next[pos + run] = EMPTY;
        rec(clueIndex + 1, pos + run + 1, next);
      } else {
        rec(clueIndex + 1, pos + run, next);
      }
    }
  };

  rec(0, 0, Array(length).fill(undefined));
  return placements;
}

function placementMatchesKnown(placement, known) {
  for (let i = 0; i < known.length; i += 1) {
    if (known[i] === UNKNOWN) continue;
    if (placement[i] !== known[i]) return false;
  }
  return true;
}

/**
 * Deduce forced cells for one line.
 * @returns {{ line: number[], changed: boolean, contradiction: boolean }}
 */
export function refineLine(known, clues) {
  const length = known.length;
  const candidates = enumerateLinePlacements(length, clues).filter((placement) =>
    placementMatchesKnown(placement, known)
  );

  if (candidates.length === 0) {
    return { line: known.slice(), changed: false, contradiction: true };
  }

  const next = known.slice();
  let changed = false;
  for (let i = 0; i < length; i += 1) {
    if (known[i] !== UNKNOWN) continue;
    const value = candidates[0][i];
    if (candidates.every((placement) => placement[i] === value)) {
      next[i] = value;
      changed = true;
    }
  }
  return { line: next, changed, contradiction: false };
}

/**
 * Pure-logic solve. Returns filled 0/1 grid, or null if incomplete/contradiction.
 */
export function logicSolve(rowClues, colClues) {
  const height = rowClues.length;
  const width = colClues.length;
  const grid = Array.from({ length: height }, () => Array(width).fill(UNKNOWN));

  let guard = 0;
  const maxPasses = width * height * 4;

  while (guard < maxPasses) {
    guard += 1;
    let changed = false;

    for (let r = 0; r < height; r += 1) {
      const result = refineLine(grid[r], rowClues[r]);
      if (result.contradiction) return null;
      if (result.changed) {
        grid[r] = result.line;
        changed = true;
      }
    }

    for (let c = 0; c < width; c += 1) {
      const column = grid.map((row) => row[c]);
      const result = refineLine(column, colClues[c]);
      if (result.contradiction) return null;
      if (result.changed) {
        for (let r = 0; r < height; r += 1) {
          grid[r][c] = result.line[r];
        }
        changed = true;
      }
    }

    if (!changed) break;
  }

  for (let r = 0; r < height; r += 1) {
    for (let c = 0; c < width; c += 1) {
      if (grid[r][c] === UNKNOWN) {
        return null;
      }
    }
  }

  return grid;
}

export function gridsEqual(a, b) {
  if (!a || !b || a.length !== b.length) return false;
  for (let r = 0; r < a.length; r += 1) {
    if (a[r].length !== b[r].length) return false;
    for (let c = 0; c < a[r].length; c += 1) {
      if (a[r][c] !== b[r][c]) return false;
    }
  }
  return true;
}

/**
 * Parse Conceptis / puzzle-nonograms.com task string.
 * Format: row0/row1/.../rowH-1/col0/.../colW-1  — clues joined with '.'
 */
export function parseTask(task, width, height) {
  const segments = task.split('/');
  if (segments.length < width + height) {
    throw new Error(`task has ${segments.length} segments, expected ${width + height}`);
  }
  const parseSeg = (seg) => {
    if (seg === '' || seg === '0') return [];
    return seg.split('.').map((n) => Number(n));
  };
  const rowClues = segments.slice(0, height).map(parseSeg);
  const colClues = segments.slice(height, height + width).map(parseSeg);
  return { rowClues, colClues };
}

export function encodeTask(rowClues, colClues) {
  const fmt = (clues) => {
    if (!clues || clues.length === 0) return '0';
    return clues.join('.');
  };
  return [...rowClues.map(fmt), ...colClues.map(fmt)].join('/');
}

export function clueComplexity(rowClues, colClues) {
  const lines = [...rowClues, ...colClues];
  const counts = lines.map((c) => c.length);
  return {
    avgCluesPerLine: counts.reduce((a, b) => a + b, 0) / counts.length,
    maxCluesOnLine: Math.max(...counts),
    multiClueLines: counts.filter((n) => n >= 2).length,
    triplePlusLines: counts.filter((n) => n >= 3).length,
  };
}
