import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { getRandomPuzzle, getPuzzleById } from '../data/nonogramPuzzles';
import apiService from '../services/apiService';
import {
  CELL_EMPTY,
  CELL_FILLED,
  CELL_MARKED,
  DRAW_ROTATE,
  DRAW_BLACK,
  DRAW_CROSS,
  DRAW_BLANK,
  STANDARD_SIZES,
  createEmptyGrid,
  cloneGrid,
  checkWin,
  checkWinByClues,
  hasErrors,
  getNextRotateValue,
  getMaxClueCount,
  autoCrossGrid,
  formatTimer,
  getDefaultCellSize,
  getRecommendedZoom,
} from '../utils/nonogramEngine';
import {
  SPECIAL_MODES,
  MODE_LABELS,
  isSpecialMode,
  buildUpstreamPuzzleUrl,
  buildUpstreamNewPuzzleUrl,
  parseNonogramPageHtml,
  parseNonogramGetPayload,
  todayISODate,
} from '../utils/nonogramUpstream';

const STORAGE_KEY = 'nonograms-game-state';
const MAX_HISTORY = 100;

const DEFAULT_SETTINGS = {
  autoCross: true,
  showTimer: true,
  highlightRowCol: true,
  nightMode: false,
};

function parseModeParam(value) {
  if (isSpecialMode(value)) return value;
  return 'standard';
}

function puzzleIsSolved(grid, puzzle) {
  if (!puzzle) return false;
  if (puzzle.solution) return checkWin(grid, puzzle.solution);
  return checkWinByClues(grid, puzzle.rowClues, puzzle.colClues);
}

function GameNonograms() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [playMode, setPlayMode] = useState(() => parseModeParam(searchParams.get('mode')));
  const [specialDate, setSpecialDate] = useState(() => searchParams.get('date') || todayISODate());
  const [size, setSize] = useState(10);
  const [puzzle, setPuzzle] = useState(null);
  const [grid, setGrid] = useState([]);
  const [gameState, setGameState] = useState('playing');
  const [statusMessage, setStatusMessage] = useState('');
  const [timer, setTimer] = useState(0);
  const [drawMode, setDrawMode] = useState(DRAW_ROTATE);
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [hoverCell, setHoverCell] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [showRules, setShowRules] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [history, setHistory] = useState([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  const [isMobile, setIsMobile] = useState(false);
  const [gameRestored, setGameRestored] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState('');
  /** Manual clue marks (click toggles orange), keys: `r-{row}-{clueIndex}` / `c-{col}-{clueIndex}` */
  const [crossedClues, setCrossedClues] = useState({});

  const timerRef = useRef(null);
  const startTimeRef = useRef(null);
  const isDraggingRef = useRef(false);
  const dragValueRef = useRef(null);
  const dragVisitedRef = useRef(new Set());
  const dragLastCellRef = useRef(null);
  const puzzleRef = useRef(null);
  const suppressHistoryRef = useRef(false);
  const historyRef = useRef([]);
  const historyIndexRef = useRef(-1);
  const fetchGenRef = useRef(0);

  puzzleRef.current = puzzle;

  const syncHistory = useCallback((entries, index) => {
    historyRef.current = entries;
    historyIndexRef.current = index;
    setHistory(entries);
    setHistoryIndex(index);
  }, []);

  const applyLoadedPuzzle = useCallback((nextPuzzle, nextSize = null) => {
    const emptyGrid = createEmptyGrid(nextPuzzle.width, nextPuzzle.height);
    setPuzzle(nextPuzzle);
    setGrid(emptyGrid);
    if (nextSize != null) setSize(nextSize);
    setGameState('playing');
    setStatusMessage('');
    setLoadError('');
    setTimer(0);
    startTimeRef.current = Date.now();
    const initialHistory = [cloneGrid(emptyGrid)];
    syncHistory(initialHistory, 0);
    setHoverCell(null);
    isDraggingRef.current = false;
    dragValueRef.current = null;
    dragVisitedRef.current = new Set();
    dragLastCellRef.current = null;
    setCrossedClues({});
    setZoom(getRecommendedZoom(nextPuzzle.width, nextPuzzle.height));
  }, [syncHistory]);

  const loadPuzzle = useCallback((nextSize, puzzleId = null) => {
    const nextPuzzle = puzzleId ? getPuzzleById(nextSize, puzzleId) : getRandomPuzzle(nextSize);
    if (!nextPuzzle) return;
    applyLoadedPuzzle(nextPuzzle, nextSize);
  }, [applyLoadedPuzzle]);

  const loadSpecialPuzzle = useCallback(async (mode, date, { prevId = null } = {}) => {
    const gen = ++fetchGenRef.current;
    setLoading(true);
    setLoadError('');
    setStatusMessage('');
    try {
      let nextPuzzle;
      if (prevId) {
        const sourceUrl = buildUpstreamNewPuzzleUrl(prevId);
        const body = await apiService.helperPass(sourceUrl);
        nextPuzzle = parseNonogramGetPayload(body, { mode, sourceUrl, date });
      } else {
        const sourceUrl = buildUpstreamPuzzleUrl(mode, date || null);
        const html = await apiService.helperPass(sourceUrl);
        nextPuzzle = parseNonogramPageHtml(html, { mode, sourceUrl, date: date || null });
      }
      if (gen !== fetchGenRef.current) return;
      if (nextPuzzle.date) setSpecialDate(nextPuzzle.date);
      applyLoadedPuzzle(nextPuzzle, Math.max(nextPuzzle.width, nextPuzzle.height));
    } catch (error) {
      if (gen !== fetchGenRef.current) return;
      console.error('Failed to load special nonogram', error);
      setLoadError(error.message || 'Daily puzzles are temporarily unavailable');
      setPuzzle(null);
      setGrid([]);
    } finally {
      if (gen === fetchGenRef.current) setLoading(false);
    }
  }, [applyLoadedPuzzle]);

  const pushHistory = useCallback((nextGrid) => {
    if (suppressHistoryRef.current) return;
    const trimmed = historyRef.current.slice(0, historyIndexRef.current + 1);
    let updated = [...trimmed, cloneGrid(nextGrid)];
    let index = updated.length - 1;
    if (updated.length > MAX_HISTORY) {
      updated = updated.slice(-MAX_HISTORY);
      index = updated.length - 1;
    }
    syncHistory(updated, index);
  }, [syncHistory]);

  const maybeAutoCross = useCallback((nextGrid) => {
    if (!settings.autoCross || !puzzleRef.current) {
      return nextGrid;
    }
    const { grid: crossed, changed } = autoCrossGrid(
      nextGrid,
      puzzleRef.current.rowClues,
      puzzleRef.current.colClues
    );
    return changed ? crossed : nextGrid;
  }, [settings.autoCross]);

  const setCell = useCallback((row, col, value, recordHistory = true) => {
    if (gameState !== 'playing' || !puzzle) return;

    setGrid((prev) => {
      if (prev[row][col] === value) {
        return prev;
      }
      const next = cloneGrid(prev);
      next[row][col] = value;
      const crossed = maybeAutoCross(next);
      if (recordHistory) {
        pushHistory(crossed);
      }
      return crossed;
    });
  }, [gameState, puzzle, maybeAutoCross, pushHistory]);

  const paintCell = useCallback((row, col, value) => {
    const key = `${row},${col}`;
    if (dragVisitedRef.current.has(key)) return;
    dragVisitedRef.current.add(key);
    setCell(row, col, value, false);
  }, [setCell]);

  const finishDrag = useCallback(() => {
    if (!isDraggingRef.current) return;
    isDraggingRef.current = false;
    dragValueRef.current = null;
    dragVisitedRef.current = new Set();
    dragLastCellRef.current = null;
    setGrid((prev) => {
      const crossed = maybeAutoCross(prev);
      pushHistory(crossed);
      return crossed;
    });
  }, [maybeAutoCross, pushHistory]);

  const cellsOnLine = (r0, c0, r1, c1) => {
    const points = [];
    let x0 = c0;
    let y0 = r0;
    const x1 = c1;
    const y1 = r1;
    const dx = Math.abs(x1 - x0);
    const dy = Math.abs(y1 - y0);
    const sx = x0 < x1 ? 1 : -1;
    const sy = y0 < y1 ? 1 : -1;
    let err = dx - dy;
    while (true) {
      points.push([y0, x0]);
      if (x0 === x1 && y0 === y1) break;
      const e2 = 2 * err;
      if (e2 > -dy) {
        err -= dy;
        x0 += sx;
      }
      if (e2 < dx) {
        err += dx;
        y0 += sy;
      }
    }
    return points;
  };

  const beginInteraction = useCallback((row, col, button = 0) => {
    if (gameState !== 'playing' || !puzzle) return;

    let value;
    if (button === 2) {
      value = CELL_MARKED;
    } else if (drawMode === DRAW_ROTATE) {
      value = getNextRotateValue(grid[row][col]);
      dragValueRef.current = value;
    } else if (drawMode === DRAW_BLACK) {
      value = CELL_FILLED;
      dragValueRef.current = value;
    } else if (drawMode === DRAW_CROSS) {
      value = CELL_MARKED;
      dragValueRef.current = value;
    } else {
      value = CELL_EMPTY;
      dragValueRef.current = value;
    }

    isDraggingRef.current = true;
    dragVisitedRef.current = new Set();
    dragLastCellRef.current = { row, col };
    paintCell(row, col, value);
  }, [gameState, puzzle, drawMode, grid, paintCell]);

  const continueInteraction = useCallback((row, col) => {
    if (!isDraggingRef.current || dragValueRef.current === null) return;
    const last = dragLastCellRef.current;
    const targets = last ? cellsOnLine(last.row, last.col, row, col) : [[row, col]];
    targets.forEach(([r, c]) => paintCell(r, c, dragValueRef.current));
    dragLastCellRef.current = { row, col };
  }, [paintCell]);

  useEffect(() => {
    const modeParam = parseModeParam(searchParams.get('mode'));
    const sizeParam = parseInt(searchParams.get('size') || '10', 10);
    const initialSize = STANDARD_SIZES.includes(sizeParam) ? sizeParam : 10;
    const dateParam = searchParams.get('date') || todayISODate();

    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const state = JSON.parse(saved);
        const savedMode = parseModeParam(state.playMode || 'standard');
        const sameStandard =
          savedMode === 'standard' &&
          modeParam === 'standard' &&
          state.size === initialSize &&
          state.puzzle &&
          state.grid &&
          state.puzzle.id === state.puzzleId;
        const sameSpecial =
          isSpecialMode(savedMode) &&
          savedMode === modeParam &&
          state.puzzle &&
          state.grid &&
          (state.specialDate || state.puzzle.date || '') === (searchParams.get('date') || state.specialDate || '');

        if (sameStandard || sameSpecial) {
          setPlayMode(savedMode);
          setPuzzle(state.puzzle);
          setGrid(state.grid);
          setSize(state.size);
          if (state.specialDate) setSpecialDate(state.specialDate);
          setGameState(state.gameState || 'playing');
          setStatusMessage(state.statusMessage || '');
          setTimer(state.timer || 0);
          setDrawMode(state.drawMode || DRAW_ROTATE);
          setSettings({ ...DEFAULT_SETTINGS, ...state.settings });
          setZoom(state.zoom || 1);
          setCrossedClues(state.crossedClues || {});
          const restoredHistory = state.history || [state.grid];
          const restoredIndex = state.historyIndex ?? restoredHistory.length - 1;
          historyRef.current = restoredHistory;
          historyIndexRef.current = restoredIndex;
          setHistory(restoredHistory);
          setHistoryIndex(restoredIndex);
          startTimeRef.current = Date.now() - (state.timer || 0) * 1000;
          setGameRestored(true);
          setTimeout(() => setGameRestored(false), 3000);
          return;
        }
      } catch (error) {
        console.error('Failed to restore nonograms state', error);
      }
    }

    setPlayMode(modeParam);
    if (isSpecialMode(modeParam)) {
      setSpecialDate(dateParam);
      loadSpecialPuzzle(modeParam, dateParam);
    } else {
      loadPuzzle(initialSize);
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const onResize = () => {
      setIsMobile(window.innerWidth <= 768 || 'ontouchstart' in window);
    };
    onResize();
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  useEffect(() => {
    if (gameState !== 'playing') {
      if (timerRef.current) clearInterval(timerRef.current);
      return undefined;
    }

    timerRef.current = setInterval(() => {
      if (startTimeRef.current) {
        setTimer(Math.floor((Date.now() - startTimeRef.current) / 1000));
      }
    }, 1000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [gameState]);

  useEffect(() => {
    const onMouseUp = () => finishDrag();
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('touchend', onMouseUp);
    return () => {
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('touchend', onMouseUp);
    };
  }, [finishDrag]);

  useEffect(() => {
    if (!puzzle || gameState !== 'playing') return;

    if (puzzleIsSolved(grid, puzzle)) {
      setGameState('won');
      setStatusMessage('Puzzle solved! Great job!');
    }
  }, [grid, puzzle, gameState]);

  useEffect(() => {
    if (!puzzle) return;

    const payload = {
      puzzleId: puzzle.id,
      puzzle,
      grid,
      size,
      playMode,
      specialDate,
      gameState,
      statusMessage,
      timer,
      drawMode,
      settings,
      zoom,
      crossedClues,
      history,
      historyIndex,
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
  }, [puzzle, grid, size, playMode, specialDate, gameState, statusMessage, timer, drawMode, settings, zoom, crossedClues, history, historyIndex]);

  const updateUrl = (next) => {
    const params = {};
    if (next.mode && next.mode !== 'standard') params.mode = next.mode;
    if (next.mode === 'standard' || !next.mode) {
      params.size = String(next.size ?? size);
    }
    if (isSpecialMode(next.mode) && next.date) {
      params.date = next.date;
    }
    setSearchParams(params);
  };

  const handleModeChange = (nextMode) => {
    setPlayMode(nextMode);
    setLoadError('');
    if (isSpecialMode(nextMode)) {
      const date = specialDate || todayISODate();
      setSpecialDate(date);
      updateUrl({ mode: nextMode, date });
      loadSpecialPuzzle(nextMode, date);
    } else {
      updateUrl({ mode: 'standard', size });
      loadPuzzle(size);
    }
  };

  const handleSizeChange = (nextSize) => {
    setPlayMode('standard');
    updateUrl({ mode: 'standard', size: nextSize });
    loadPuzzle(nextSize);
  };

  const handleDateChange = (nextDate) => {
    setSpecialDate(nextDate);
    if (!isSpecialMode(playMode)) return;
    updateUrl({ mode: playMode, date: nextDate });
    loadSpecialPuzzle(playMode, nextDate);
  };

  const handleNewPuzzle = () => {
    if (isSpecialMode(playMode)) {
      if (puzzle?.externalPuzzleId) {
        loadSpecialPuzzle(playMode, specialDate, { prevId: puzzle.externalPuzzleId });
      } else {
        loadSpecialPuzzle(playMode, specialDate);
      }
      return;
    }
    loadPuzzle(size);
  };

  const handleStartOver = () => {
    if (!puzzle) return;
    const emptyGrid = createEmptyGrid(puzzle.width, puzzle.height);
    setGrid(emptyGrid);
    setGameState('playing');
    setStatusMessage('');
    setTimer(0);
    setCrossedClues({});
    startTimeRef.current = Date.now();
    const initialHistory = [cloneGrid(emptyGrid)];
    syncHistory(initialHistory, 0);
  };

  const handleFallbackStandard = () => {
    setLoadError('');
    handleModeChange('standard');
  };

  const toggleClueMark = (key) => {
    setCrossedClues((prev) => {
      const next = { ...prev };
      if (next[key]) {
        delete next[key];
      } else {
        next[key] = true;
      }
      return next;
    });
  };

  const handleUndo = useCallback(() => {
    if (historyIndexRef.current <= 0) return;
    const nextIndex = historyIndexRef.current - 1;
    suppressHistoryRef.current = true;
    setGrid(cloneGrid(historyRef.current[nextIndex]));
    syncHistory(historyRef.current, nextIndex);
    setGameState('playing');
    setStatusMessage('');
    suppressHistoryRef.current = false;
  }, [syncHistory]);

  const handleRedo = useCallback(() => {
    if (historyIndexRef.current >= historyRef.current.length - 1) return;
    const nextIndex = historyIndexRef.current + 1;
    suppressHistoryRef.current = true;
    setGrid(cloneGrid(historyRef.current[nextIndex]));
    syncHistory(historyRef.current, nextIndex);
    setGameState('playing');
    setStatusMessage('');
    suppressHistoryRef.current = false;
  }, [syncHistory]);

  const handleDone = () => {
    if (!puzzle) return;
    if (puzzleIsSolved(grid, puzzle)) {
      setGameState('won');
      setStatusMessage('Puzzle solved! Great job!');
      return;
    }
    if (puzzle.solution && hasErrors(grid, puzzle.solution)) {
      setStatusMessage('Some filled cells are incorrect. Keep trying!');
      return;
    }
    setStatusMessage('Not complete yet — keep filling in the picture!');
  };

  const handleContextMenu = (event) => {
    event.preventDefault();
  };

  useEffect(() => {
    const onKeyDown = (event) => {
      const tag = event.target?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || event.target?.isContentEditable) {
        return;
      }

      const key = event.key.toLowerCase();
      const mod = event.ctrlKey || event.metaKey;

      if (mod && key === 'z' && !event.shiftKey) {
        event.preventDefault();
        handleUndo();
        return;
      }
      if (mod && (key === 'y' || (key === 'z' && event.shiftKey))) {
        event.preventDefault();
        handleRedo();
        return;
      }

      if (mod) return;

      if (key === '1' || key === 'r') {
        setDrawMode(DRAW_ROTATE);
      } else if (key === '2' || key === 'b') {
        setDrawMode(DRAW_BLACK);
      } else if (key === '3' || key === 'x') {
        setDrawMode(DRAW_CROSS);
      } else if (key === '4' || key === 'e') {
        setDrawMode(DRAW_BLANK);
      } else if (key === 'n') {
        setSettings((prev) => ({ ...prev, nightMode: !prev.nightMode }));
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [handleUndo, handleRedo]);

  const maxRowClues = puzzle ? getMaxClueCount(puzzle.rowClues) : 0;
  const maxColClues = puzzle ? getMaxClueCount(puzzle.colClues) : 0;
  const cellSize = puzzle ? getDefaultCellSize(puzzle.width, puzzle.height, zoom) : 20;
  const clueFontSize = Math.max(10, Math.round(cellSize * 0.45));
  const rowClueWidth = maxRowClues * cellSize;
  const colClueHeight = maxColClues * cellSize;
  const canUndo = historyIndex > 0;
  const canRedo = historyIndex < history.length - 1;

  const getCellClass = (row, col) => {
    const value = grid[row][col];
    const classes = ['cell'];
    if (value === CELL_FILLED) classes.push('filled');
    if (value === CELL_MARKED) classes.push('marked');
    if (settings.highlightRowCol && hoverCell) {
      if (hoverCell.row === row && hoverCell.col === col) {
        classes.push('hover-cross');
      } else if (hoverCell.row === row || hoverCell.col === col) {
        classes.push('highlighted');
      }
    }
    if (col === 0) classes.push('thick-left');
    if (row === 0) classes.push('thick-top');
    if ((row + 1) % 5 === 0) classes.push('thick-bottom');
    if ((col + 1) % 5 === 0) classes.push('thick-right');
    return classes.join(' ');
  };

  const getClueClass = (type, row, col, crossed) => {
    const classes = ['task-cell', type];
    if (crossed) classes.push('cross');
    if (settings.highlightRowCol) {
      if (type === 'row-task' && hoverCell?.row === row) classes.push('highlighted');
      if (type === 'col-task' && hoverCell?.col === col) classes.push('highlighted');
    }
    return classes.join(' ');
  };

  const renderBoard = () => (
    <div className="puzzle-board-outer">
      <div className="puzzle-board-inner">
        {/* Column clues — borders between columns only (not between stacked numbers) */}
        <div className="puzzle-board-header" style={{ paddingLeft: rowClueWidth }}>
          {puzzle.colClues.map((clues, col) => {
            const colClasses = ['clue-column'];
            if (col === 0) colClasses.push('thick-left');
            if ((col + 1) % 5 === 0) colClasses.push('thick-right');
            return (
              <div
                key={`col-clues-${col}`}
                className={colClasses.join(' ')}
                style={{ width: cellSize, height: colClueHeight }}
              >
                {Array.from({ length: maxColClues }).map((_, clueRow) => {
                  const clueIndex = clueRow - (maxColClues - clues.length);
                  const clue = clueIndex >= 0 ? clues[clueIndex] : null;
                  const clueKey = `c-${col}-${clueIndex}`;
                  const crossed = clue !== null && !!crossedClues[clueKey];
                  return (
                    <div
                      key={`col-clue-${col}-${clueRow}`}
                      className={getClueClass('col-task', clueRow, col, crossed)}
                      style={{
                        width: cellSize,
                        height: cellSize,
                        fontSize: clueFontSize,
                        cursor: clue !== null ? 'pointer' : 'default',
                      }}
                      onClick={() => {
                        if (clue !== null) toggleClueMark(clueKey);
                      }}
                      role={clue !== null ? 'button' : undefined}
                      title={clue !== null ? 'Mark clue' : undefined}
                    >
                      {clue || ''}
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>

        {/* Rows: row clues + cells — borders between rows only (not between numbers in a row) */}
        {grid.map((row, rowIndex) => {
          const rowClues = puzzle.rowClues[rowIndex];
          const rowClasses = ['puzzle-board-row'];
          if ((rowIndex + 1) % 5 === 0) rowClasses.push('thick-bottom-row');
          return (
            <div
              key={`board-row-${rowIndex}`}
              className={rowClasses.join(' ')}
            >
              <div
                className={`row-clue-strip${rowIndex === 0 ? ' thick-top' : ''}`}
                style={{ width: rowClueWidth, height: cellSize }}
              >
                {Array.from({ length: maxRowClues }).map((_, clueCol) => {
                  const clueIndex = clueCol - (maxRowClues - rowClues.length);
                  const clue = clueIndex >= 0 ? rowClues[clueIndex] : null;
                  const clueKey = `r-${rowIndex}-${clueIndex}`;
                  const crossed = clue !== null && !!crossedClues[clueKey];
                  return (
                    <div
                      key={`row-clue-${rowIndex}-${clueCol}`}
                      className={getClueClass('row-task', rowIndex, clueCol, crossed)}
                      style={{
                        width: cellSize,
                        height: cellSize,
                        fontSize: clueFontSize,
                        cursor: clue !== null ? 'pointer' : 'default',
                      }}
                      onClick={() => {
                        if (clue !== null) toggleClueMark(clueKey);
                      }}
                      role={clue !== null ? 'button' : undefined}
                      title={clue !== null ? 'Mark clue' : undefined}
                    >
                      {clue || ''}
                    </div>
                  );
                })}
              </div>

              {row.map((cell, colIndex) => (
                <div
                  key={`cell-${rowIndex}-${colIndex}`}
                  className={getCellClass(rowIndex, colIndex)}
                  style={{ width: cellSize, height: cellSize }}
                  onMouseDown={(e) => {
                    e.preventDefault();
                    beginInteraction(rowIndex, colIndex, e.button);
                  }}
                  onMouseEnter={() => {
                    setHoverCell({ row: rowIndex, col: colIndex });
                    continueInteraction(rowIndex, colIndex);
                  }}
                  onContextMenu={(e) => {
                    e.preventDefault();
                    beginInteraction(rowIndex, colIndex, 2);
                  }}
                  onTouchStart={(e) => {
                    e.preventDefault();
                    const touchMode = drawMode === DRAW_CROSS ? 2 : 0;
                    beginInteraction(rowIndex, colIndex, touchMode);
                  }}
                  onTouchMove={(e) => {
                    e.preventDefault();
                    const touch = e.touches[0];
                    const target = document.elementFromPoint(touch.clientX, touch.clientY);
                    const rowAttr = target?.getAttribute?.('data-row');
                    const colAttr = target?.getAttribute?.('data-col');
                    if (rowAttr != null && colAttr != null) {
                      const r = parseInt(rowAttr, 10);
                      const c = parseInt(colAttr, 10);
                      setHoverCell({ row: r, col: c });
                      continueInteraction(r, c);
                    }
                  }}
                  data-row={rowIndex}
                  data-col={colIndex}
                >
                  {cell === CELL_MARKED && <span className="mark-x">✕</span>}
                </div>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className={`nonograms-page${settings.nightMode ? ' night' : ''}`}>
      <div className="nonograms-container">
        <h1 className="nonograms-title">Nonograms</h1>

        {gameRestored && <div className="restore-msg">Previous game restored</div>}

        <ul className="mode-menu">
          {['standard', ...SPECIAL_MODES].map((mode) => (
            <li key={mode}>
              <button
                type="button"
                className={playMode === mode ? 'active' : ''}
                onClick={() => handleModeChange(mode)}
                disabled={loading}
              >
                {MODE_LABELS[mode]}
              </button>
            </li>
          ))}
        </ul>

        {playMode === 'standard' ? (
          <ul className="size-menu">
            {STANDARD_SIZES.map((puzzleSize) => (
              <li key={puzzleSize}>
                <button
                  type="button"
                  className={size === puzzleSize ? 'active' : ''}
                  onClick={() => handleSizeChange(puzzleSize)}
                >
                  {puzzleSize}×{puzzleSize}
                </button>
              </li>
            ))}
          </ul>
        ) : (
          <div className="date-row">
            <label htmlFor="nonogram-date">
              Date
              <input
                id="nonogram-date"
                type="date"
                value={specialDate}
                onChange={(e) => handleDateChange(e.target.value)}
                disabled={loading}
              />
            </label>
          </div>
        )}

        {loadError && (
          <div className="load-error" role="alert">
            <p>{loadError}</p>
            <p className="load-error-hint">
              Special puzzles need a logged-in session and a reachable backend proxy.
            </p>
            <button type="button" className="btn-secondary" onClick={handleFallbackStandard}>
              Switch to Standard
            </button>
          </div>
        )}

        {loading && <div className="loading-msg">Loading puzzle via proxy…</div>}

        {puzzle && (
          <div className="puzzle-info">
            {puzzle.name} ({puzzle.width}×{puzzle.height})
            {puzzle.sourced === 'task-seed' ? ' · classic clues' : ''}
            {puzzle.generated ? ' · generated' : ''}
            {puzzle.sourced?.startsWith('upstream') ? ' · via helper/pass' : ''}
          </div>
        )}

        <div className="top-controls">
          {settings.showTimer && (
            <input className="clock" readOnly value={formatTimer(timer)} title="Timer" />
          )}
          <button type="button" className="icon-btn" onClick={handleUndo} disabled={!canUndo || loading} title="Undo (Ctrl+Z)">↩</button>
          <button type="button" className="icon-btn" onClick={handleRedo} disabled={!canRedo || loading} title="Redo (Ctrl+Y)">↪</button>
          <button type="button" className="btn-done" onClick={handleDone} disabled={!puzzle || loading}>Done</button>
          <button type="button" className="btn-secondary" onClick={handleNewPuzzle} disabled={loading}>
            {isSpecialMode(playMode) ? 'Reload' : 'New Puzzle'}
          </button>
          <button type="button" className="btn-secondary" onClick={handleStartOver} disabled={!puzzle || loading}>Start Over</button>
          <button
            type="button"
            className={`btn-secondary${showSettings ? ' active-toggle' : ''}`}
            onClick={() => setShowSettings((p) => !p)}
            title="Settings"
          >
            Settings
          </button>
        </div>

        {showSettings && (
          <div className="settings-panel" role="region" aria-label="Game settings">
            <label className="setting-row">
              <input
                type="checkbox"
                checked={settings.autoCross}
                onChange={(e) => setSettings((prev) => ({ ...prev, autoCross: e.target.checked }))}
              />
              Auto-cross completed lines
            </label>
            <label className="setting-row">
              <input
                type="checkbox"
                checked={settings.showTimer}
                onChange={(e) => setSettings((prev) => ({ ...prev, showTimer: e.target.checked }))}
              />
              Show timer
            </label>
            <label className="setting-row">
              <input
                type="checkbox"
                checked={settings.highlightRowCol}
                onChange={(e) => setSettings((prev) => ({ ...prev, highlightRowCol: e.target.checked }))}
              />
              Highlight row / column
            </label>
            <label className="setting-row">
              <input
                type="checkbox"
                checked={settings.nightMode}
                onChange={(e) => setSettings((prev) => ({ ...prev, nightMode: e.target.checked }))}
              />
              Night mode (N)
            </label>
            <div className="shortcuts-hint">
              Keys: 1/R Rotate · 2/B Black · 3/X Cross · 4/E Blank · Ctrl+Z/Y Undo/Redo
            </div>
          </div>
        )}

        {size >= 15 && (
          <div className="zoom-row">
            <label htmlFor="zoom-slider">Zoom</label>
            <input
              id="zoom-slider"
              type="range"
              min="0.6"
              max="2"
              step="0.05"
              value={zoom}
              onChange={(e) => setZoom(parseFloat(e.target.value))}
            />
            <span>{Math.round(zoom * 100)}%</span>
          </div>
        )}

        <div className="draw-toolbar">
          {[
            { id: DRAW_ROTATE, label: 'Rotate', icon: '↻', hint: '1 / R' },
            { id: DRAW_BLACK, label: 'Black', icon: '■', swatch: true, hint: '2 / B' },
            { id: DRAW_CROSS, label: 'Cross', icon: '✕', hint: '3 / X' },
            { id: DRAW_BLANK, label: 'Blank', icon: '○', hint: '4 / E' },
          ].map((mode) => (
            <button
              key={mode.id}
              type="button"
              className={`draw-btn ${drawMode === mode.id ? 'active' : ''}`}
              onClick={() => setDrawMode(mode.id)}
              title={mode.hint}
            >
              {mode.swatch ? <span className="swatch-black" /> : <span>{mode.icon}</span>}
              {mode.label}
            </button>
          ))}
        </div>

        <div
          className="puzzle-scroll"
          onMouseLeave={() => setHoverCell(null)}
          onContextMenu={handleContextMenu}
        >
          {puzzle && !loading ? renderBoard() : null}
        </div>

        <div className={`status-msg ${gameState === 'won' ? 'won' : ''}`}>{statusMessage}</div>

        {gameState === 'won' && (
          <div className="win-actions">
            <button type="button" className="btn-done" onClick={handleNewPuzzle}>
              {isSpecialMode(playMode) ? 'Reload Puzzle' : 'Play Another Puzzle'}
            </button>
          </div>
        )}

        {isSpecialMode(playMode) && (
          <p className="attribution">
            Calendar puzzles from{' '}
            <a href="https://www.puzzle-nonograms.com/" target="_blank" rel="noreferrer">
              puzzle-nonograms.com
            </a>
            {' '}(proxied via backend helper/pass).
          </p>
        )}

        <div className="rules-section">
          <button type="button" className="rules-toggle" onClick={() => setShowRules((p) => !p)}>
            {showRules ? 'Hide the rules' : 'Show the rules'}
          </button>
          {showRules && (
            <div className="rules-box">
              <p><strong>Nonograms</strong> is a logic puzzle with simple rules and challenging solutions.</p>
              <p>
                You have a grid of squares, which must be either filled in black or marked with X.
                Beside each row are listed the lengths of the runs of black squares on that row.
                Above each column are listed the lengths of the runs of black squares in that column.
              </p>
              <p>
                Left click on a square to make it black. Right click to mark with X.
                Click and drag to mark more than one square.
              </p>
              <p>
                Keyboard: <kbd>1</kbd>/<kbd>R</kbd> Rotate, <kbd>2</kbd>/<kbd>B</kbd> Black,
                {' '}<kbd>3</kbd>/<kbd>X</kbd> Cross, <kbd>4</kbd>/<kbd>E</kbd> Blank,
                {' '}<kbd>Ctrl</kbd>+<kbd>Z</kbd>/<kbd>Y</kbd> Undo/Redo, <kbd>N</kbd> Night mode.
              </p>
              {isMobile && <p>Use the Black or Cross toolbar buttons on mobile, then tap and drag.</p>}
            </div>
          )}
        </div>
      </div>

      <style>{`
        .nonograms-page {
          --ng-bg: #fff;
          --ng-text: #333;
          --ng-muted: #666;
          --ng-panel: #f5f5f5;
          --ng-border: #bbb;
          --ng-title: #c00;
          --ng-board-bg: #fff;
          --ng-board-line: #000;
          --ng-highlight: #cfe6ff;
          --ng-hover: #9ec4ea;
          --ng-mark: #c00;
          --ng-clock-bg: #fff;
          min-height: calc(100vh - 120px);
          background: var(--ng-bg);
          padding: 12px 8px 24px;
          transition: background 0.2s ease, color 0.2s ease;
        }
        .nonograms-page.night {
          --ng-bg: #1a1d21;
          --ng-text: #e8e8e8;
          --ng-muted: #a8a8a8;
          --ng-panel: #2a2f36;
          --ng-border: #555;
          --ng-title: #ff6b6b;
          --ng-board-bg: #f4f4f4;
          --ng-highlight: #3a5a7a;
          --ng-hover: #4a7aad;
          --ng-mark: #ff5555;
          --ng-clock-bg: #2a2f36;
        }
        .nonograms-container {
          max-width: 1100px;
          margin: 0 auto;
          text-align: center;
          font-family: Arial, Helvetica, sans-serif;
          color: var(--ng-text);
        }
        .nonograms-title {
          font-size: 1.5rem;
          font-weight: bold;
          margin: 0 0 12px;
          color: var(--ng-title);
        }
        .restore-msg { color: #080; font-size: 0.85rem; margin-bottom: 8px; }
        .nonograms-page.night .restore-msg { color: #6dce6d; }
        .mode-menu, .size-menu {
          list-style: none; padding: 0; margin: 0 0 10px;
          display: flex; flex-wrap: wrap; justify-content: center; gap: 4px;
        }
        .mode-menu button, .size-menu button {
          border: 1px solid var(--ng-border); background: var(--ng-panel); padding: 4px 10px;
          font-size: 0.8rem; cursor: pointer; border-radius: 3px; color: var(--ng-text);
        }
        .mode-menu button.active, .size-menu button.active {
          background: var(--ng-bg); border-color: var(--ng-title); color: var(--ng-title); font-weight: bold;
        }
        .mode-menu button:disabled { opacity: 0.55; cursor: default; }
        .date-row {
          display: flex; justify-content: center; align-items: center;
          gap: 8px; margin-bottom: 12px; font-size: 0.85rem; color: var(--ng-text);
        }
        .date-row input[type="date"] {
          margin-left: 6px; padding: 4px 8px; border: 1px solid var(--ng-border);
          border-radius: 3px; background: var(--ng-panel); color: var(--ng-text);
        }
        .loading-msg { color: var(--ng-muted); font-size: 0.9rem; margin-bottom: 10px; }
        .load-error {
          border: 1px solid #c62828; background: #ffebee; color: #b71c1c;
          padding: 10px 12px; border-radius: 4px; margin: 0 auto 12px; max-width: 520px;
          font-size: 0.9rem; text-align: left;
        }
        .night .load-error { background: #3e2723; color: #ffcdd2; border-color: #ef9a9a; }
        .load-error-hint { margin: 6px 0 10px; font-size: 0.8rem; opacity: 0.9; }
        .attribution {
          font-size: 0.8rem; color: var(--ng-muted); margin: 12px 0 0;
        }
        .attribution a { color: var(--ng-title); }
        .puzzle-info { font-size: 0.85rem; color: var(--ng-muted); margin-bottom: 10px; }
        .top-controls {
          display: flex; flex-wrap: wrap; justify-content: center;
          align-items: center; gap: 6px; margin-bottom: 10px;
        }
        .clock {
          width: 64px; text-align: center; font-size: 0.95rem; font-weight: bold;
          border: 1px solid var(--ng-border); border-radius: 4px; padding: 5px 4px;
          background: var(--ng-clock-bg); color: var(--ng-text);
        }
        .icon-btn {
          width: 32px; height: 32px; border: 1px solid var(--ng-border); border-radius: 4px;
          background: var(--ng-panel); cursor: pointer; font-size: 1rem; color: var(--ng-text);
        }
        .icon-btn:disabled { opacity: 0.4; cursor: default; }
        .btn-done {
          background: #4a90d9; color: #fff; border: 1px solid #3a7bc8;
          border-radius: 4px; padding: 6px 16px; font-weight: bold; cursor: pointer; font-size: 0.9rem;
        }
        .btn-secondary {
          background: var(--ng-panel); border: 1px solid var(--ng-border); border-radius: 4px;
          padding: 6px 12px; cursor: pointer; font-size: 0.85rem; color: var(--ng-text);
        }
        .btn-secondary.active-toggle {
          border-color: #4a90d9; background: #e8f0fe; color: #1a4a7a;
        }
        .nonograms-page.night .btn-secondary.active-toggle {
          background: #2a4058; color: #cde; border-color: #4a90d9;
        }
        .settings-panel {
          display: flex; flex-wrap: wrap; justify-content: center; gap: 10px 18px;
          align-items: center; margin: 0 auto 12px; padding: 10px 12px;
          max-width: 720px; background: var(--ng-panel); border: 1px solid var(--ng-border);
          border-radius: 6px; text-align: left;
        }
        .shortcuts-hint {
          width: 100%; text-align: center; font-size: 0.75rem; color: var(--ng-muted);
        }
        .zoom-row {
          display: flex; justify-content: center; align-items: center;
          gap: 8px; margin-bottom: 10px; font-size: 0.85rem;
        }
        .draw-toolbar {
          display: flex; flex-wrap: wrap; justify-content: center;
          gap: 4px; margin-bottom: 10px;
        }
        .draw-btn {
          display: inline-flex; align-items: center; gap: 4px;
          border: 1px solid var(--ng-border); border-radius: 4px; background: var(--ng-panel);
          padding: 5px 10px; cursor: pointer; font-size: 0.8rem; color: var(--ng-text);
          transition: background 0.12s ease, border-color 0.12s ease;
        }
        .draw-btn.active { background: #e8f0fe; border-color: #4a90d9; color: #1a4a7a; }
        .nonograms-page.night .draw-btn.active { background: #2a4058; color: #cde; }
        .swatch-black { display: inline-block; width: 12px; height: 12px; background: #000; }
        .setting-row {
          display: inline-flex; align-items: center; gap: 6px;
          font-size: 0.85rem; cursor: pointer; margin: 0;
        }
        .puzzle-scroll {
          overflow: auto; display: flex; justify-content: center;
          margin-bottom: 12px; -webkit-overflow-scrolling: touch;
          padding: 4px;
        }

        .puzzle-board-outer {
          display: inline-block;
          border: 2px solid var(--ng-board-line);
          background: var(--ng-board-bg);
          line-height: 0;
          font-family: Tahoma, Geneva, Verdana, sans-serif;
          box-shadow: 0 1px 4px rgba(0,0,0,0.12);
        }
        .puzzle-board-inner { display: inline-block; }
        .puzzle-board-header {
          display: flex;
          background: var(--ng-board-bg);
          position: relative;
        }
        .puzzle-board-header::before {
          content: '';
          position: absolute;
          left: 0; top: 0;
          width: ${rowClueWidth}px;
          height: ${colClueHeight}px;
          background: var(--ng-board-bg);
          border: none;
        }
        .clue-column {
          display: flex;
          flex-direction: column;
          justify-content: flex-end;
          flex-shrink: 0;
          box-sizing: border-box;
          border-left: 1px solid var(--ng-board-line);
          border-top: 1px solid var(--ng-board-line);
          border-bottom: 1px solid var(--ng-board-line);
        }
        .puzzle-board-header .clue-column:last-child {
          border-right: 1px solid var(--ng-board-line);
        }
        .clue-column.thick-left { border-left: 2px solid var(--ng-board-line) !important; }
        .clue-column.thick-right { border-right: 2px solid var(--ng-board-line) !important; }
        .puzzle-board-row { display: flex; flex-shrink: 0; }
        .row-clue-strip {
          display: flex;
          flex-shrink: 0;
          background: var(--ng-board-bg);
          box-sizing: border-box;
          border-top: 1px solid var(--ng-board-line);
          border-left: 1px solid var(--ng-board-line);
          border-right: 1px solid var(--ng-board-line);
        }
        .puzzle-board-row:last-child .row-clue-strip {
          border-bottom: 1px solid var(--ng-board-line);
        }
        .puzzle-board-row.thick-bottom-row .row-clue-strip {
          border-bottom: 2px solid var(--ng-board-line);
        }
        .task-cell {
          display: flex;
          align-items: center;
          justify-content: center;
          box-sizing: border-box;
          border: none;
          background: transparent;
          color: #000;
          font-weight: 700;
          flex-shrink: 0;
          line-height: 1;
          transition: background 0.1s ease, color 0.12s ease;
        }
        .task-cell.row-task {
          justify-content: flex-end;
          padding-right: ${Math.max(4, Math.round(cellSize * 0.2))}px;
        }
        .task-cell.cross { color: #ff6600; }
        .task-cell.highlighted { background: var(--ng-highlight) !important; }
        .cell {
          box-sizing: border-box;
          border-top: 1px solid var(--ng-board-line);
          border-left: 1px solid var(--ng-board-line);
          border-right: none;
          border-bottom: none;
          background: var(--ng-board-bg);
          cursor: pointer;
          flex-shrink: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          line-height: 1;
          position: relative;
          user-select: none;
          -webkit-user-select: none;
          touch-action: none;
          transition: background-color 0.08s ease;
        }
        .puzzle-board-row .cell:last-child { border-right: 1px solid var(--ng-board-line); }
        .puzzle-board-row:last-child .cell { border-bottom: 1px solid var(--ng-board-line); }
        /* Conceptis-style: black fill inset with white gap inside the black grid line */
        .cell.filled {
          background: var(--ng-board-bg);
        }
        .cell.filled::after {
          content: '';
          position: absolute;
          top: 1px;
          left: 1px;
          right: 1px;
          bottom: 1px;
          background: #000;
          pointer-events: none;
        }
        .cell.marked { background: var(--ng-board-bg); }
        .cell.highlighted:not(.filled) { background: var(--ng-highlight) !important; }
        .cell.hover-cross:not(.filled) { background: var(--ng-hover) !important; }
        .cell .mark-x {
          color: var(--ng-mark);
          font-size: ${Math.max(11, Math.round(cellSize * 0.55))}px;
          font-weight: normal;
          pointer-events: none;
          line-height: 1;
          animation: ng-mark-in 0.12s ease;
        }
        @keyframes ng-mark-in {
          from { opacity: 0; transform: scale(0.55); }
          to { opacity: 1; transform: scale(1); }
        }
        .thick-left { border-left: 2px solid var(--ng-board-line) !important; }
        .thick-top { border-top: 2px solid var(--ng-board-line) !important; }
        .thick-right { border-right: 2px solid var(--ng-board-line) !important; }
        .thick-bottom { border-bottom: 2px solid var(--ng-board-line) !important; }

        .status-msg {
          min-height: 1.4rem; font-size: 0.95rem; font-weight: bold;
          color: var(--ng-muted); margin-bottom: 8px;
        }
        .status-msg.won {
          color: #080;
          animation: ng-win-pulse 0.45s ease;
        }
        .nonograms-page.night .status-msg.won { color: #6dce6d; }
        @keyframes ng-win-pulse {
          0% { transform: scale(0.96); opacity: 0.5; }
          100% { transform: scale(1); opacity: 1; }
        }
        .win-actions { margin-bottom: 12px; }
        .rules-section { text-align: left; max-width: 600px; margin: 0 auto; }
        .rules-toggle {
          color: var(--ng-title); background: none; border: none; cursor: pointer;
          font-size: 0.85rem; font-weight: bold; padding: 0; margin-bottom: 6px;
        }
        .rules-box { font-size: 0.85rem; line-height: 1.5; color: var(--ng-muted); }
        .rules-box p { margin: 0 0 8px; }
        .rules-box kbd {
          display: inline-block; padding: 1px 5px; margin: 0 1px;
          border: 1px solid var(--ng-border); border-radius: 3px;
          background: var(--ng-panel); font-size: 0.78rem; color: var(--ng-text);
        }
        @media (max-width: 640px) {
          .nonograms-container { max-width: 100%; }
          .shortcuts-hint { display: none; }
        }
      `}</style>
    </div>
  );
}

export default GameNonograms;
