import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';
import apiService from '../services/apiService';
import API_CONFIG from '../config/api';
import LoadingSpinner from '../components/LoadingSpinner';
import Notification from '../components/Notification';

function buildSshWebSocketUrl(serverId, inline) {
  const token = localStorage.getItem('auth_token');
  if (!token) {
    throw new Error('You must be signed in to open an SSH session.');
  }
  const base = new URL(API_CONFIG.BASE_URL);
  const wsProto = base.protocol === 'https:' ? 'wss:' : 'ws:';
  let path = `/api/v1/ssh/ws/${encodeURIComponent(serverId)}?token=${encodeURIComponent(token)}`;
  if (inline) {
    path += '&inline=1';
  }
  return `${wsProto}//${base.host}${path}`;
}

const CRED_MODE = {
  STORED: 'stored',
  INLINE_PW: 'inline_pw',
  INLINE_KEY: 'inline_key',
};

const SshClient = () => {
  const [servers, setServers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [notification, setNotification] = useState(null);

  const [name, setName] = useState('');
  const [host, setHost] = useState('');
  const [port, setPort] = useState('22');
  const [username, setUsername] = useState('');
  const [authMode, setAuthMode] = useState('password');
  const [password, setPassword] = useState('');
  const [privateKeyPem, setPrivateKeyPem] = useState('');
  const [keyPassphrase, setKeyPassphrase] = useState('');
  const [clearPassword, setClearPassword] = useState(false);
  const [clearPrivateKey, setClearPrivateKey] = useState(false);
  const [clearKeyPassphrase, setClearKeyPassphrase] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [saving, setSaving] = useState(false);

  const [selectedServerId, setSelectedServerId] = useState('');
  const [credentialMode, setCredentialMode] = useState(CRED_MODE.STORED);
  const [inlinePassword, setInlinePassword] = useState('');
  const [inlinePrivateKey, setInlinePrivateKey] = useState('');
  const [inlineKeyPassphrase, setInlineKeyPassphrase] = useState('');

  const [sessionStatus, setSessionStatus] = useState('idle');
  const [isServerModalOpen, setIsServerModalOpen] = useState(false);
  const terminalRef = useRef(null);
  const wsRef = useRef(null);
  const termInstanceRef = useRef(null);
  const fitAddonRef = useRef(null);
  const onResizeRef = useRef(null);
  const encoderRef = useRef(null);

  const loadServers = useCallback(async () => {
    setLoading(true);
    try {
      const list = await apiService.getSshServers();
      setServers(Array.isArray(list) ? list : []);
    } catch (e) {
      setNotification({ type: 'error', message: e.message || 'Failed to load SSH servers' });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadServers();
  }, [loadServers]);

  const teardownSession = useCallback(() => {
    if (onResizeRef.current) {
      window.removeEventListener('resize', onResizeRef.current);
      onResizeRef.current = null;
    }
    if (wsRef.current) {
      const w = wsRef.current;
      wsRef.current = null;
      try {
        w.onclose = null;
        w.close();
      } catch {
        /* ignore */
      }
    }
    if (termInstanceRef.current) {
      try {
        termInstanceRef.current.dispose();
      } catch {
        /* ignore */
      }
      termInstanceRef.current = null;
    }
    fitAddonRef.current = null;
    encoderRef.current = null;
    setSessionStatus('idle');
  }, []);

  useEffect(() => () => teardownSession(), [teardownSession]);

  const sendResize = useCallback((ws, term) => {
    if (!ws || ws.readyState !== WebSocket.OPEN || !term) return;
    try {
      ws.send(
        JSON.stringify({
          type: 'resize',
          cols: term.cols,
          rows: term.rows,
        })
      );
    } catch {
      /* ignore */
    }
  }, []);

  const connectSsh = useCallback(async () => {
    if (!selectedServerId) {
      setNotification({ type: 'error', message: 'Select an SSH server.' });
      return;
    }

    let detail;
    try {
      detail = await apiService.getSshServer(selectedServerId);
    } catch (e) {
      setNotification({ type: 'error', message: e.message || 'Could not load server details.' });
      return;
    }

    const useInline =
      credentialMode === CRED_MODE.INLINE_PW || credentialMode === CRED_MODE.INLINE_KEY;

    if (!useInline) {
      if (detail.auth_mode === 'password' && !detail.password) {
        setNotification({
          type: 'error',
          message:
            'No password saved for this profile. Use inline password or edit the server to store one.',
        });
        return;
      }
      if (detail.auth_mode === 'publickey' && !detail.private_key_pem) {
        setNotification({
          type: 'error',
          message:
            'No private key saved for this profile. Use inline key or edit the server to store one.',
        });
        return;
      }
    } else {
      if (credentialMode === CRED_MODE.INLINE_PW && detail.auth_mode !== 'password') {
        setNotification({
          type: 'error',
          message: 'Inline password applies to servers with password authentication.',
        });
        return;
      }
      if (credentialMode === CRED_MODE.INLINE_KEY && detail.auth_mode !== 'publickey') {
        setNotification({
          type: 'error',
          message: 'Inline private key applies to servers with public key authentication.',
        });
        return;
      }
      if (credentialMode === CRED_MODE.INLINE_PW && !inlinePassword.trim()) {
        setNotification({ type: 'error', message: 'Enter the password for this session.' });
        return;
      }
      if (credentialMode === CRED_MODE.INLINE_KEY && !inlinePrivateKey.trim()) {
        setNotification({ type: 'error', message: 'Paste your private key PEM for this session.' });
        return;
      }
    }

    teardownSession();

    const el = terminalRef.current;
    if (!el) return;

    const term = new Terminal({
      cursorBlink: true,
      fontSize: 14,
      theme: {
        background: '#1e1e1e',
        foreground: '#d4d4d4',
      },
    });
    const fitAddon = new FitAddon();
    term.loadAddon(fitAddon);
    term.open(el);
    fitAddon.fit();

    termInstanceRef.current = term;
    fitAddonRef.current = fitAddon;
    encoderRef.current = new TextEncoder();

    let url;
    try {
      url = buildSshWebSocketUrl(selectedServerId, useInline);
    } catch (e) {
      setNotification({ type: 'error', message: e.message });
      term.dispose();
      termInstanceRef.current = null;
      return;
    }

    const ws = new WebSocket(url);
    ws.binaryType = 'arraybuffer';
    wsRef.current = ws;
    setSessionStatus('connecting');

    ws.onopen = () => {
      setSessionStatus('connected');
      if (useInline) {
        fitAddon.fit();
        const payload = {
          cols: term.cols,
          rows: term.rows,
        };
        if (credentialMode === CRED_MODE.INLINE_PW) {
          payload.password = inlinePassword;
        } else {
          payload.private_key = inlinePrivateKey;
          if (inlineKeyPassphrase) {
            payload.key_passphrase = inlineKeyPassphrase;
          }
        }
        ws.send(JSON.stringify(payload));
      } else {
        sendResize(ws, term);
      }

      term.onData((data) => {
        if (ws.readyState === WebSocket.OPEN && encoderRef.current) {
          ws.send(encoderRef.current.encode(data));
        }
      });

      const onResize = () => {
        if (!fitAddonRef.current || !termInstanceRef.current) return;
        try {
          fitAddonRef.current.fit();
          sendResize(wsRef.current, termInstanceRef.current);
        } catch {
          /* ignore */
        }
      };
      onResizeRef.current = onResize;
      window.addEventListener('resize', onResize);
    };

    ws.onmessage = (ev) => {
      if (typeof ev.data === 'string') {
        try {
          const j = JSON.parse(ev.data);
          if (j.error) {
            setNotification({ type: 'error', message: j.error });
          }
        } catch {
          /* ignore non-json text */
        }
        return;
      }
      const buf = new Uint8Array(ev.data);
      term.write(buf);
    };

    ws.onerror = () => {
      setNotification({ type: 'error', message: 'WebSocket error.' });
    };

    ws.onclose = () => {
      if (wsRef.current === ws) {
        wsRef.current = null;
      }
      if (onResizeRef.current) {
        window.removeEventListener('resize', onResizeRef.current);
        onResizeRef.current = null;
      }
      if (termInstanceRef.current) {
        try {
          termInstanceRef.current.dispose();
        } catch {
          /* ignore */
        }
        termInstanceRef.current = null;
      }
      fitAddonRef.current = null;
      encoderRef.current = null;
      setSessionStatus('idle');
    };
  }, [
    selectedServerId,
    credentialMode,
    inlinePassword,
    inlinePrivateKey,
    inlineKeyPassphrase,
    sendResize,
    teardownSession,
  ]);

  const resetForm = () => {
    setName('');
    setHost('');
    setPort('22');
    setUsername('');
    setAuthMode('password');
    setPassword('');
    setPrivateKeyPem('');
    setKeyPassphrase('');
    setClearPassword(false);
    setClearPrivateKey(false);
    setClearKeyPassphrase(false);
    setEditingId(null);
  };

  const startEdit = async (id) => {
    try {
      const d = await apiService.getSshServer(id);
      setIsServerModalOpen(true);
      setEditingId(id);
      setName(d.name || '');
      setHost(d.host || '');
      setPort(String(d.port ?? 22));
      setUsername(d.username || '');
      setAuthMode(d.auth_mode === 'publickey' ? 'publickey' : 'password');
      setPassword('');
      setPrivateKeyPem('');
      setKeyPassphrase('');
      setClearPassword(false);
      setClearPrivateKey(false);
      setClearKeyPassphrase(false);
    } catch (e) {
      setNotification({ type: 'error', message: e.message || 'Failed to load server' });
    }
  };

  const saveServer = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const portNum = parseInt(port, 10);
      if (Number.isNaN(portNum)) {
        throw new Error('Invalid port');
      }
      const payload = {
        name: name.trim(),
        host: host.trim(),
        port: portNum,
        username: username.trim(),
        auth_mode: authMode,
      };
      if (authMode === 'password') {
        if (password.trim()) payload.password = password.trim();
        if (editingId && clearPassword) payload.clear_password = true;
      } else {
        if (privateKeyPem.trim()) payload.private_key_pem = privateKeyPem.trim();
        if (keyPassphrase.trim()) payload.key_passphrase = keyPassphrase.trim();
        if (editingId && clearPrivateKey) payload.clear_private_key = true;
        if (editingId && clearKeyPassphrase) payload.clear_key_passphrase = true;
      }

      if (editingId) {
        await apiService.updateSshServer(editingId, payload);
        setNotification({ type: 'success', message: 'SSH server updated.' });
      } else {
        await apiService.createSshServer(payload);
        setNotification({ type: 'success', message: 'SSH server created.' });
      }
      resetForm();
      await loadServers();
    } catch (err) {
      setNotification({ type: 'error', message: err.message || 'Save failed' });
    } finally {
      setSaving(false);
    }
  };

  const deleteServer = async (id) => {
    if (!window.confirm('Delete this SSH server entry?')) return;
    try {
      await apiService.deleteSshServer(id);
      setNotification({ type: 'success', message: 'Deleted.' });
      if (selectedServerId === id) {
        setSelectedServerId('');
      }
      await loadServers();
    } catch (e) {
      setNotification({ type: 'error', message: e.message || 'Delete failed' });
    }
  };

  const selected = servers.find((s) => s.id === selectedServerId);

  return (
    <div className="min-h-screen bg-gray-50 py-6 px-4">
      <div className="max-w-7xl mx-auto">
        <div className="mb-8">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <h1 className="text-3xl font-bold text-gray-900">SSH Client</h1>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => {
                  resetForm();
                  setIsServerModalOpen(true);
                }}
                className="inline-flex rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
              >
                Manage Servers
              </button>
              <button
                type="button"
                onClick={loadServers}
                className="inline-flex rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
              >
                Refresh
              </button>
            </div>
          </div>
          <p className="mt-2 text-gray-600">
            Manage SSH targets and open interactive shells through the backend (admin only). The browser uses{' '}
            <code className="text-sm bg-gray-200 px-1 rounded">WebSocket → backend → SSH</code>. Password and key
            material may be stored on the server or supplied per session from this browser.
          </p>
        </div>

        {notification && (
          <Notification
            type={notification.type}
            message={notification.message}
            onClose={() => setNotification(null)}
          />
        )}

        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">Session</h2>
          <div className="space-y-3">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div>
                <label className="block text-sm font-medium text-gray-700">Server</label>
                <select
                  className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                  value={selectedServerId}
                  onChange={(e) => setSelectedServerId(e.target.value)}
                >
                  <option value="">— Select —</option>
                  {servers.map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.name} ({s.username}@{s.host})
                    </option>
                  ))}
                </select>
              </div>
              {selected && (
                <div className="rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-gray-700">
                  <div className="font-medium text-gray-900">Selected</div>
                  <div>{selected.username}@{selected.host}:{selected.port}</div>
                  <div className="text-xs text-gray-500 mt-1">Profile auth: {selected.auth_mode}</div>
                </div>
              )}
            </div>

            <div>
              <span className="block text-sm font-medium text-gray-700 mb-2">Credentials for this connection</span>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                <label className="flex items-center gap-2 rounded border border-gray-200 px-3 py-2 text-sm">
                  <input
                    type="radio"
                    name="cred"
                    checked={credentialMode === CRED_MODE.STORED}
                    onChange={() => setCredentialMode(CRED_MODE.STORED)}
                  />
                  Use backend-stored secret
                </label>
                <label className="flex items-center gap-2 rounded border border-gray-200 px-3 py-2 text-sm">
                  <input
                    type="radio"
                    name="cred"
                    checked={credentialMode === CRED_MODE.INLINE_PW}
                    onChange={() => setCredentialMode(CRED_MODE.INLINE_PW)}
                    disabled={!selected || selected.auth_mode !== 'password'}
                  />
                  Password from browser
                </label>
                <label className="flex items-center gap-2 rounded border border-gray-200 px-3 py-2 text-sm">
                  <input
                    type="radio"
                    name="cred"
                    checked={credentialMode === CRED_MODE.INLINE_KEY}
                    onChange={() => setCredentialMode(CRED_MODE.INLINE_KEY)}
                    disabled={!selected || selected.auth_mode !== 'publickey'}
                  />
                  Private key from browser
                </label>
              </div>
            </div>

            {credentialMode === CRED_MODE.INLINE_PW && (
              <div>
                <label className="block text-sm font-medium text-gray-700">Session password</label>
                <input
                  type="password"
                  className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                  value={inlinePassword}
                  onChange={(e) => setInlinePassword(e.target.value)}
                  autoComplete="off"
                />
              </div>
            )}

            {credentialMode === CRED_MODE.INLINE_KEY && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700">Private key PEM</label>
                  <textarea
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm font-mono"
                    rows={4}
                    value={inlinePrivateKey}
                    onChange={(e) => setInlinePrivateKey(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Key passphrase (optional)</label>
                  <input
                    type="password"
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                    value={inlineKeyPassphrase}
                    onChange={(e) => setInlineKeyPassphrase(e.target.value)}
                    autoComplete="off"
                  />
                </div>
              </div>
            )}

            <div className="flex flex-wrap gap-2 items-center">
              <button
                type="button"
                onClick={connectSsh}
                disabled={sessionStatus === 'connecting' || sessionStatus === 'connected'}
                className="inline-flex rounded-md bg-green-600 px-4 py-2 text-sm font-medium text-white hover:bg-green-700 disabled:opacity-50"
              >
                Connect
              </button>
              <button
                type="button"
                onClick={teardownSession}
                disabled={sessionStatus === 'idle'}
                className="inline-flex rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50"
              >
                Disconnect
              </button>
              <span className="text-xs text-gray-500">Status: {sessionStatus}</span>
            </div>
          </div>

          <div className="mt-4 rounded-md border border-gray-800 bg-black overflow-hidden" style={{ minHeight: '66vh' }}>
            <div ref={terminalRef} className="h-full min-h-[66vh] w-full p-1" />
          </div>
        </div>
      </div>

      {isServerModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4">
          <div className="w-full max-w-5xl max-h-[90vh] overflow-hidden rounded-lg bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-gray-200 px-5 py-4">
              <h2 className="text-lg font-semibold text-gray-900">Manage SSH Servers</h2>
              <button
                type="button"
                onClick={() => setIsServerModalOpen(false)}
                className="rounded px-2 py-1 text-sm text-gray-600 hover:bg-gray-100"
              >
                Close
              </button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 p-5 overflow-y-auto max-h-[calc(90vh-72px)]">
              <div>
                <h3 className="text-md font-medium text-gray-900 mb-3">Server list</h3>
                {loading ? (
                  <LoadingSpinner />
                ) : servers.length === 0 ? (
                  <p className="text-gray-500 text-sm">No SSH servers yet. Add one on the right.</p>
                ) : (
                  <ul className="divide-y divide-gray-200 border border-gray-200 rounded-md">
                    {servers.map((s) => (
                      <li key={s.id} className="flex items-center justify-between px-3 py-2 text-sm">
                        <div>
                          <div className="font-medium text-gray-900">{s.name}</div>
                          <div className="text-gray-500">
                            {s.username}@{s.host}:{s.port} · {s.auth_mode}
                          </div>
                        </div>
                        <div className="flex gap-2 shrink-0">
                          <button type="button" onClick={() => startEdit(s.id)} className="text-blue-600 hover:underline">
                            Edit
                          </button>
                          <button type="button" onClick={() => deleteServer(s.id)} className="text-red-600 hover:underline">
                            Delete
                          </button>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              <form onSubmit={saveServer} className="space-y-3">
                <h3 className="text-md font-medium text-gray-900">{editingId ? 'Edit server' : 'Add server'}</h3>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Name</label>
                  <input
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Host</label>
                    <input
                      className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                      value={host}
                      onChange={(e) => setHost(e.target.value)}
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Port</label>
                    <input
                      className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                      type="number"
                      value={port}
                      onChange={(e) => setPort(e.target.value)}
                      required
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Username</label>
                  <input
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Auth mode</label>
                  <select
                    className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                    value={authMode}
                    onChange={(e) => setAuthMode(e.target.value)}
                  >
                    <option value="password">Password</option>
                    <option value="publickey">Public key</option>
                  </select>
                </div>
                {authMode === 'password' ? (
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Password (optional if using inline-only)</label>
                    <input
                      type="password"
                      className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      autoComplete="off"
                    />
                    {editingId && (
                      <label className="mt-2 flex items-center gap-2 text-sm text-gray-600">
                        <input
                          type="checkbox"
                          checked={clearPassword}
                          onChange={(e) => setClearPassword(e.target.checked)}
                        />
                        Clear stored password
                      </label>
                    )}
                  </div>
                ) : (
                  <>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        Private key PEM (optional if using browser-only key)
                      </label>
                      <textarea
                        className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm font-mono"
                        rows={6}
                        value={privateKeyPem}
                        onChange={(e) => setPrivateKeyPem(e.target.value)}
                        placeholder="-----BEGIN OPENSSH PRIVATE KEY-----"
                      />
                      {editingId && (
                        <label className="mt-2 flex items-center gap-2 text-sm text-gray-600">
                          <input
                            type="checkbox"
                            checked={clearPrivateKey}
                            onChange={(e) => setClearPrivateKey(e.target.checked)}
                          />
                          Clear stored private key
                        </label>
                      )}
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">Key passphrase (optional)</label>
                      <input
                        type="password"
                        className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                        value={keyPassphrase}
                        onChange={(e) => setKeyPassphrase(e.target.value)}
                        autoComplete="off"
                      />
                      {editingId && (
                        <label className="mt-2 flex items-center gap-2 text-sm text-gray-600">
                          <input
                            type="checkbox"
                            checked={clearKeyPassphrase}
                            onChange={(e) => setClearKeyPassphrase(e.target.checked)}
                          />
                          Clear stored passphrase
                        </label>
                      )}
                    </div>
                  </>
                )}
                <div className="flex gap-2 pt-2">
                  <button
                    type="submit"
                    disabled={saving}
                    className="inline-flex justify-center rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
                  >
                    {saving ? 'Saving…' : editingId ? 'Update' : 'Create'}
                  </button>
                  {editingId && (
                    <button type="button" onClick={resetForm} className="text-sm text-gray-600 hover:text-gray-900">
                      Cancel edit
                    </button>
                  )}
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SshClient;
