function puzzleFromTask(size, task, index) {
  try {
    const { rowClues, colClues } = parseTask(task, size, size);
    const solution = logicSolve(rowClues, colClues);
    if (!solution) return null;
    return {
      id: `${size}-seed-${index}`,
      name: `Classic ${size}×${size} #${index + 1}`,
      width: size,
      height: size,
      rowClues,
      colClues,
      solution,
      task: encodeTask(rowClues, colClues),
      complexity: clueComplexity(rowClues, colClues),
      sourced: 'task-seed',
    };
  } catch (error) {
    console.warn('Failed to build seed puzzle', size, index, error);
    return null;
  }
}

function buildSeedBank(size) {
  const tasks = SEED_TASKS[size] || [];
  return tasks.map((task, index) => puzzleFromTask(size, task, index)).filter(Boolean);
}

function getSeedBank(size) {
  if (!SEED_BANK_CACHE[size]) {
    SEED_BANK_CACHE[size] = buildSeedBank(size);
  }
  return SEED_BANK_CACHE[size];
}

const SEED_BANK_CACHE = {};

/** Tiny emergency fallbacks if generation fails (should be rare). */
const FALLBACK_PUZZLES = {
  5: [
    buildPuzzleFromPattern('5-fallback', 'Fallback', [
      '###..',
      '..#..',
      '..###',
      '#.#.#',
      '##.##',
    ]),
  ],
  10: [buildPuzzleFromPattern('10-fallback-diamond', 'Fallback', diamondPattern(10))],
};

export const STANDARD_PUZZLES = new Proxy(
  {},
  {
    get(_target, prop) {
      const size = Number(prop);
      if (!Number.isFinite(size)) return undefined;
      return getSeedBank(size);
    },
  }
);

/**
 * New game: mix generated puzzles with live-sampled seed tasks so difficulty
 * matches puzzle-nonograms.com (~50% density, multi-segment clues).
 */
export function getRandomPuzzle(size) {
  const seeds = getSeedBank(size);

  // Larger boards: prefer authentic seed tasks (generation can be heavy).
  const preferSeed = size >= 20 ? 0.7 : size >= 15 ? 0.45 : 0.3;
  if (seeds.length > 0 && Math.random() < preferSeed) {
    return seeds[Math.floor(Math.random() * seeds.length)];
  }

  const generated = generatePuzzleForSize(size);
  if (generated) {
    return generated;
  }

  if (seeds.length > 0) {
    return seeds[Math.floor(Math.random() * seeds.length)];
  }

  const fallback = FALLBACK_PUZZLES[size];
  if (fallback?.length) {
    return fallback[Math.floor(Math.random() * fallback.length)];
  }

  return null;
}

export function getPuzzleById(size, id) {
  const seeds = getSeedBank(size);
  const found = seeds.find((puzzle) => puzzle.id === id);
  if (found) return found;

  const fallback = FALLBACK_PUZZLES[size] || [];
  return fallback.find((puzzle) => puzzle.id === id) || null;
}

/** Exposed for debugging / future online catalog import. */
export function getSeedPuzzles(size) {
  return getSeedBank(size);
}
